// プレゼン教材 第4期（第40〜52週）。作り方は docs/プレゼン教材_作り方.md
window.PRESENT=(window.PRESENT||[]).concat([
 {week:40, level:"B1+", length:"5分", title:"プレゼンの設計図",
  skill:"話の地図を最初に見せ、「道しるべ」の言葉で区切りながら、5分の事業紹介を最後まで通せる。",
  lesson:[
   "第4期のはじめは、プレゼン全体の「設計図」を作る練習です。英語のプレゼンは「これから話すことを言う → 話す → 話したことをまとめる」の3段が基本です。最初に話の地図（今日の流れ）を見せると、聞き手は安心してついてきてくれます。",
   "話の区切りには、必ず「道しるべ」の言葉を置きます。Let me start with...（まず〜から）、Moving on to...（次は〜に移ります）、That brings me to...（そこで〜の話になります）、To conclude...（まとめると）。この4つだけで、聞き手は「今どこを聞いているか」がわかります。日本語のように黙ってスライドを替えるのではなく、言葉で区切りを伝えるのが英語の礼儀です。",
   "5分のプレゼンなら、スライドは5〜6枚で十分です。目安は、はじめ1分・本論3分・まとめ1分。本論は3つまでにしぼりましょう。4つ以上になると、聞き手は覚えきれません。",
   "まとめでは新しい話を出さず、3つの要点をもう一度短く言います。最後に Thank you. と質問への呼びかけで終わると、きれいに締まります。今週の手本は、岩田さんの3つの仕事（院・しくみ・日本酒）と、おもてなしのお手伝いを、インドのホテルの方に紹介する5分の話です。"
  ],
  structure:[
   {en:"Opening and purpose",ja:"あいさつと目的"},
   {en:"Agenda (the map)",ja:"今日の流れ（話の地図）"},
   {en:"Main points 1–3 with signposts",ja:"本論1〜3（道しるべでつなぐ）"},
   {en:"Summary",ja:"まとめ（要点をくり返す）"},
   {en:"Thanks and questions",ja:"お礼と質問の呼びかけ"}
  ],
  phrases:[
   {en:"Today I'd like to talk about how we could work together.",ja:"今日は、私たちがどう一緒に仕事ができるかについてお話しします。",note:"目的を最初の1文で言う。I want to より I'd like to がていねい。"},
   {en:"My talk is divided into three parts.",ja:"私の話は3つに分かれています。",note:"数を先に言うと、聞き手が数えながら聞ける。"},
   {en:"Let me start with my background.",ja:"まず、私の経歴からお話しします。",note:"本論の1つめに入る合図。"},
   {en:"Moving on to my second point.",ja:"2つめの点に移ります。",note:"スライドを替える前に言う。"},
   {en:"That brings me to the most important part.",ja:"そこで、いちばん大切なところになります。",note:"前の話と次の話をつなげたいときに。"},
   {en:"Let me give you an example.",ja:"例を1つ挙げます。",note:"抽象的な話のあとにすぐ使う。"},
   {en:"I'll come back to this point later.",ja:"この点は、あとでまた触れます。",note:"今くわしく話さない、と予告する。"},
   {en:"To conclude, let me sum up the three key points.",ja:"まとめとして、3つの要点をくり返します。",note:"まとめに入る合図。新しい話は出さない。"},
   {en:"Please feel free to ask questions at the end.",ja:"質問は最後に、どうぞ遠慮なくお聞きください。",note:"質問のタイミングを最初に決めておくと落ち着ける。"},
   {en:"Thank you for your time. I'd be happy to answer any questions.",ja:"お時間をいただきありがとうございました。ご質問にお答えします。",note:"締めの決まり文句。笑顔で、ゆっくり。"}
  ],
  model:{title:"インドのホテルの方への事業紹介（5分）", time:"5分", note:"話す相手（ホテルの方）は練習用の場面です。",
   lines:[
    {en:"Good morning, everyone. Thank you very much for inviting me to speak with you today.",ja:"皆さん、おはようございます。本日はお招きいただき、ありがとうございます。"},
    {en:"My name is Akihiro Iwata, and I come from Japan.",ja:"岩田章弘と申します。日本から来ました。"},
    {en:"I'm a licensed acupuncturist and judo therapist, and I run a clinic in Ozu, a small city in Ehime.",ja:"私は鍼灸師・柔道整復師で、愛媛県の小さな市、大洲で院を営んでいます。"},
    {en:"Today I'd like to talk about how Japanese care and hospitality can support your hotel here in India.",ja:"今日は、日本のケアとおもてなしが、こちらインドの皆さんのホテルをどう支えられるかをお話しします。"},
    {en:"My talk is divided into three parts, and it will take about five minutes.",ja:"話は3つに分かれていて、5分ほどです。"},
    {en:"First, I'll introduce my clinic and my background. Second, I'll explain my three main areas of work.",ja:"まず、私の院と経歴をご紹介します。次に、私の3つの主な仕事を説明します。"},
    {en:"Finally, I'll suggest how we could work together. Please feel free to ask questions at the end.",ja:"最後に、一緒にできることをご提案します。質問は最後にどうぞ遠慮なくお聞きください。"},
    {en:"Let me start with my clinic. I opened it in October 2018, near JR Iyo-Ozu Station.",ja:"まず私の院からお話しします。2018年10月に、JR伊予大洲駅の近くで開業しました。"},
    {en:"Today we are a team of four staff, and we see local patients every day.",ja:"今はスタッフ4名のチームで、毎日地域の患者さんを診ています。"},
    {en:"We offer acupuncture, care for injuries and sports injuries, posture and pelvic care, and care for mothers after childbirth.",ja:"鍼灸、けがやスポーツ外傷のケア、姿勢・骨盤のケア、産後のケアを行っています。"},
    {en:"Before I opened the clinic, I worked as an athletic trainer for high school, university, corporate and professional teams.",ja:"開業の前は、高校・大学・実業団・プロのチームでアスレティックトレーナーをしていました。"},
    {en:"That experience taught me one important thing. Give your full effort to the person in front of you.",ja:"その経験から、大切なことを1つ学びました。目の前の人に全力を尽くすことです。"},
    {en:"Moving on to my three main areas of work. The first one is hospitality consulting for companies in India.",ja:"次に、私の3つの主な仕事に移ります。1つめは、インドの企業向けのおもてなしコンサルです。"},
    {en:"I help hotels, restaurants and clinics welcome Japanese guests, and Indian guests who love Japan, with real omotenashi.",ja:"ホテル、レストラン、クリニックが、日本人のお客様や日本好きのインドのお客様を、本物のおもてなしで迎えるお手伝いをしています。"},
    {en:"Omotenashi means caring for your guest before they ask. It lives in small things, like a quiet greeting or a warm towel.",ja:"おもてなしとは、お客様に言われる前に気づかうことです。静かなあいさつや温かいおしぼりのような、小さなことに表れます。"},
    {en:"The second area is a booking and customer management system. I built it first for my own clinic.",ja:"2つめは、予約と顧客管理のしくみです。最初は自分の院のために作りました。"},
    {en:"Every day, I check three numbers: sales, the number of visits, and the rate of returning patients.",ja:"私は毎日、売上・来院数・再来院率の3つの数字を見ています。"},
    {en:"Now I provide this system to partner clinics, and I support them with management consulting.",ja:"今はこのしくみを提携院に提供し、経営コンサルティングで支えています。"},
    {en:"The third area is Japanese sake. My family runs Odani Sake Ten, a sake shop founded in 1957.",ja:"3つめは日本酒です。家族が1957年創業の酒店、小谷酒店を営んでいます。"},
    {en:"I'm the International Affairs Manager, so I introduce Japanese sake to partners overseas.",ja:"私は国際担当なので、海外のパートナーに日本酒を紹介しています。"},
    {en:"That brings me to the most important part: how we could work together.",ja:"そこで、いちばん大切なところ、一緒にどう仕事ができるかの話になります。"},
    {en:"I believe these three areas connect. Good care, good systems and good hospitality all start from the same idea.",ja:"この3つはつながっていると思います。よいケア、よいしくみ、よいおもてなしは、どれも同じ考えから始まります。"},
    {en:"Let me give you an example. Your staff could learn simple Japanese greetings and ways to care for tired guests.",ja:"例を1つ挙げます。スタッフの皆さんが、日本式のかんたんなあいさつや、疲れたお客様への気づかいを学ぶことができます。"},
    {en:"Then a simple system could help you remember each guest and follow up after their stay.",ja:"そして、かんたんなしくみで一人ひとりのお客様を覚え、滞在のあとにもご連絡できます。"},
    {en:"We could also plan a Japanese evening with sake for your guests from Japan. I'll come back to this idea later.",ja:"日本からのお客様のために、日本酒を楽しむ日本の夜を企画することもできます。この案には、あとでまた触れます。"},
    {en:"Of course, every hotel is different. So my first step would be to visit you and listen carefully.",ja:"もちろん、ホテルごとに事情はちがいます。ですから、最初の一歩は、おうかがいしてじっくりお話を聞くことです。"},
    {en:"To conclude, let me sum up the three key points.",ja:"まとめとして、3つの要点をくり返します。"},
    {en:"First, I bring hands-on experience from a real clinic in Japan. Second, I offer hospitality, systems and sake together.",ja:"1つめ、日本の実際の院での現場の経験があります。2つめ、おもてなし・しくみ・日本酒をまとめてご提供できます。"},
    {en:"And third, I always start by listening to your needs.",ja:"そして3つめ、私はいつも、皆さんのご要望を聞くことから始めます。"},
    {en:"Thank you very much for your time. I'd be happy to answer any questions now.",ja:"お時間をいただき、ありがとうございました。ここからご質問にお答えします。"}
   ]},
  task:"自分の3つの仕事（院・予約と顧客管理のしくみ・日本酒）と、おもてなしのお手伝いを、インドのホテルの担当者に5分で紹介する。道しるべの4つの言葉を必ず使う。",
  taskEn:"Give a 5-minute introduction of your work to managers of a hotel group in India. Show an agenda first, and use the signposts 'Let me start with', 'Moving on to', 'That brings me to' and 'To conclude'.",
  qa:[
   {q:"How long have you been running your clinic?",a:"I opened my clinic in October 2018, so I have been running it since then.",ja:"院はどのくらい続けていますか？／2018年10月に開業したので、それからずっと続けています。"},
   {q:"What does omotenashi mean in simple words?",a:"It means caring for your guest before they ask. It's about noticing small things.",ja:"おもてなしとは、かんたんに言うと何ですか？／言われる前にお客様を気づかうことです。小さなことに気づくことです。"},
   {q:"Which of your three services should we start with?",a:"I suggest we start with hospitality training. It's simple, and your guests will feel the difference quickly.",ja:"3つのうち、どれから始めるのがよいですか？／おもてなしの研修から始めるのがよいと思います。かんたんで、お客様もすぐにちがいを感じます。"},
   {q:"Do you visit India often?",a:"Yes, I visit India regularly to meet my partners. I'd be glad to visit your hotel next time.",ja:"インドにはよく来ますか？／はい、パートナーに会うため定期的に来ています。次はぜひホテルにうかがいたいです。"}
  ],
  check:[
   "最初の1分で、目的と「話は3つ」を言えたか",
   "Let me start with / Moving on to / That brings me to / To conclude の4つを全部使えたか",
   "まとめで新しい話を出さず、3つの要点をくり返せたか",
   "経歴は本当のことだけを話したか（盛っていないか）",
   "5分以内（4分30秒〜5分）に収まったか"
  ],
  slide:"2枚めに「今日の流れ」を3行だけ書き、話すたびにその行の色を変えると、聞き手が今どこかわかります。"},
 {week:41, level:"B1+", length:"5分", title:"グラフとデータを説明する",
  skill:"グラフの線の動き（上がる・下がる・横ばい・山）と、by / to / from を正しく使って、数字の話を5分で伝えられる。",
  lesson:[
   "今週は、グラフと数字を英語で説明する練習です。グラフを見せるときは、①何のグラフか（縦と横は何か）②いちばん大事な動き ③その理由 ④そこから言えること、の4つの順で話すと、聞き手は迷いません。いきなり細かい数字から話さないのがコツです。",
   "線の動きを表す言葉は、rise / increase（上がる）、fall / drop（下がる）、remain stable（横ばい）、peak（山になる・いちばん高くなる）を覚えましょう。前置詞もとても大事です。from 55% to 70% は「55%から70%へ」、by 15 points は「15ポイント分」の差を表します。rose to 70%（70%まで上がった）と rose by 70%（70%も上がった）は意味が大きくちがうので、気をつけましょう。",
   "数字はたくさん言いすぎないこと。1枚のスライドで言う数字は2〜3個までにします。大きな数字は「約」をつけて丸めると、聞き取りやすくなります（about 1,200 = about twelve hundred）。インドの方は lakh（10万）や crore（1,000万）という単位も使うので、聞かれたら落ち着いて言い直してもらいましょう。",
   "今週の手本は、予約と顧客管理のしくみを使った院の数字の変化を説明する話です。数字はすべて練習用の例です。本番では、岩田さん自身の数字に入れかえて話しましょう。"
  ],
  structure:[
   {en:"Introduce the chart",ja:"何のグラフかを言う"},
   {en:"The main trend",ja:"いちばん大事な動き"},
   {en:"Details and reasons",ja:"細かい動きと理由"},
   {en:"What it means for you",ja:"聞き手にとっての意味"},
   {en:"Summary",ja:"まとめ"}
  ],
  phrases:[
   {en:"This chart shows the rate of returning patients over twelve months.",ja:"このグラフは、12か月間の再来院率を示しています。",note:"最初に「何のグラフか」を言う。"},
   {en:"The vertical axis shows the percentage, and the horizontal axis shows the months.",ja:"縦軸は割合、横軸は月を表しています。",note:"軸の説明は1文で短く。"},
   {en:"As you can see, the number rose steadily.",ja:"ご覧のとおり、数字は着実に上がりました。",note:"いちばん大事な動きを先に言う。"},
   {en:"It increased from 55% to 70%.",ja:"55%から70%に上がりました。",note:"from 〜 to は「〜から〜へ」。"},
   {en:"That's a rise of 15 points.",ja:"15ポイントの上昇です。",note:"by / of は「差の大きさ」を表す。"},
   {en:"Sales remained stable during the summer.",ja:"夏の間、売上は横ばいでした。",note:"remain stable = 大きく変わらない。"},
   {en:"Visits peaked in December.",ja:"来院数は12月に最も多くなりました。",note:"peak は動詞としても使える。"},
   {en:"The number dropped slightly in February.",ja:"2月に数字が少し下がりました。",note:"slightly（少し）、sharply（大きく）で程度を足す。"},
   {en:"The main reason for this is the reminder messages.",ja:"この主な理由は、お知らせのメッセージです。",note:"動きのあとに必ず理由をひとこと。"},
   {en:"What this tells us is simple.",ja:"ここからわかることは、シンプルです。",note:"数字から「言えること」へ移る合図。"}
  ],
  model:{title:"予約のしくみで院の数字はどう変わったか（5分）", time:"5分", note:"数字は練習用の例です。自分の数字に入れかえましょう。",
   lines:[
    {en:"Good afternoon, everyone. Today I'd like to show you some numbers from a clinic that uses our booking system.",ja:"皆さん、こんにちは。今日は、私たちの予約のしくみを使っている院の数字をお見せします。"},
    {en:"I'll talk about three charts: returning patients, monthly visits, and sales.",ja:"3つのグラフについてお話しします。再来院、月ごとの来院数、そして売上です。"},
    {en:"Please remember that these numbers are an example to explain the idea.",ja:"これらの数字は、考え方を説明するための例だということをご了承ください。"},
    {en:"Let me start with the first chart. This chart shows the rate of returning patients over twelve months.",ja:"まず1つめのグラフです。このグラフは、12か月間の再来院率を示しています。"},
    {en:"The vertical axis shows the percentage, and the horizontal axis shows the months.",ja:"縦軸は割合、横軸は月を表しています。"},
    {en:"As you can see, the rate rose steadily. It increased from 55% to 70%.",ja:"ご覧のとおり、再来院率は着実に上がりました。55%から70%に上がりました。"},
    {en:"That's a rise of 15 points in one year.",ja:"1年で15ポイントの上昇です。"},
    {en:"The main reason for this is the reminder messages.",ja:"この主な理由は、お知らせのメッセージです。"},
    {en:"The system sends a short message a few days after each visit. It asks how the patient is feeling.",ja:"しくみが、来院の数日後に短いメッセージを送ります。患者さんの体の調子をたずねるものです。"},
    {en:"Patients feel cared for, so they come back before the pain gets worse.",ja:"患者さんは気にかけてもらえていると感じるので、痛みが悪くなる前にまた来てくれます。"},
    {en:"Moving on to the second chart. This one shows the number of visits each month.",ja:"2つめのグラフに移ります。こちらは月ごとの来院数です。"},
    {en:"From April to July, visits remained stable at about 600 a month.",ja:"4月から7月まで、来院数は月に約600回で横ばいでした。"},
    {en:"Then they rose sharply in the autumn, and they peaked in December at about 780.",ja:"その後、秋に大きく増え、12月に約780回で最も多くなりました。"},
    {en:"December is a busy month in Japan. People want to feel good before the New Year holidays.",ja:"日本では12月は忙しい月です。お正月休みの前に体を整えたい人が多いのです。"},
    {en:"In February, the number dropped slightly to about 700. February is a short and cold month.",ja:"2月には、約700回へと少し下がりました。2月は短くて寒い月です。"},
    {en:"Even so, it stayed higher than in the spring.",ja:"それでも、春よりは高いままでした。"},
    {en:"So over the whole year, monthly visits rose from about 600 to about 700. That's an increase of around 100 visits.",ja:"つまり1年全体で、月の来院数は約600回から約700回に上がりました。約100回の増加です。"},
    {en:"Please notice one thing. The line did not jump suddenly. It climbed slowly, month by month.",ja:"1つ注目してください。線は急に跳ね上がったのではありません。月ごとに少しずつ上がりました。"},
    {en:"This tells me that the change came from daily habits, not from one big campaign.",ja:"これは、変化が1回の大きなキャンペーンではなく、毎日の習慣から生まれたことを示しています。"},
    {en:"That brings me to the third chart, sales.",ja:"そこで3つめのグラフ、売上の話になります。"},
    {en:"Sales grew by about 18% over the year. That's a little faster than the growth in visits.",ja:"売上は1年で約18%伸びました。来院数の伸びより少し速いです。"},
    {en:"Why? Because returning patients often choose a full course of care, not just one treatment.",ja:"なぜでしょうか。再来院の患者さんは、1回の施術だけでなく、続けてケアを受けることが多いからです。"},
    {en:"So the key number is not the number of new patients. It's the number of patients who come back.",ja:"つまり、大事な数字は新しい患者さんの数ではありません。また来てくれる患者さんの数です。"},
    {en:"Let me explain how I use these charts every day.",ja:"私がこれらのグラフを毎日どう使っているかを説明します。"},
    {en:"Every morning, I check sales, visits and the rate of returning patients. It takes only five minutes.",ja:"毎朝、売上・来院数・再来院率を確認します。5分しかかかりません。"},
    {en:"If one number falls, I can act quickly. For example, I can call patients who haven't come back.",ja:"どれかの数字が下がったら、すぐに動けます。たとえば、来なくなった患者さんに電話をすることができます。"},
    {en:"If one number rises, I share the good news with my staff. They like to see the result of their care.",ja:"どれかの数字が上がったら、スタッフにその知らせを伝えます。自分たちのケアの成果を見るのは、うれしいものです。"},
    {en:"And if the numbers remain stable for a long time, I ask myself what we could try next.",ja:"そして数字が長い間横ばいなら、次に何を試せるかを自分に問いかけます。"},
    {en:"What this tells us is simple. When you watch the right numbers, you can care for people better.",ja:"ここからわかることはシンプルです。正しい数字を見ていれば、人をもっとよくケアできるのです。"},
    {en:"I believe the same idea can work for clinics and wellness centres in India.",ja:"同じ考え方は、インドのクリニックやウェルネスセンターでも使えると思います。"},
    {en:"Your numbers may look different, of course. But the three charts will tell you a clear story.",ja:"もちろん、皆さんの数字はちがって見えるでしょう。でも、3つのグラフがはっきりとした流れを教えてくれます。"},
    {en:"To conclude, let me sum up. First, the rate of returning patients rose from 55% to 70%.",ja:"まとめます。1つめ、再来院率は55%から70%に上がりました。"},
    {en:"Second, visits peaked in December and stayed strong after that. Third, sales grew by about 18%.",ja:"2つめ、来院数は12月に最も多くなり、そのあとも高いままでした。3つめ、売上は約18%伸びました。"},
    {en:"And the most important lesson is this: watch the patients who come back.",ja:"そして最も大切な教えはこれです。また来てくれる患者さんを見ることです。"},
    {en:"Thank you for listening. I'd be happy to take your questions about the charts.",ja:"ご清聴ありがとうございました。グラフについてのご質問をお受けします。"}
   ]},
  task:"自分の院（または提携院）の数字のグラフを3枚用意し、上がる・下がる・横ばい・山と by / to / from を使って、インドのクリニックの経営者に5分で説明する。",
  taskEn:"Present three charts about a clinic's numbers (returning patients, visits, sales) to clinic owners in India for 5 minutes. Use rise, fall, remain stable, peak, and by / to / from correctly.",
  qa:[
   {q:"Why did visits drop in February?",a:"February is short and cold, so some patients stay at home. But the number stayed higher than in the spring.",ja:"なぜ2月に来院数が下がったのですか？／2月は短くて寒いので、家にいる患者さんがいます。でも春よりは高いままでした。"},
   {q:"Is the 18% growth because of the system alone?",a:"Not alone. The system helps, but the staff's care is just as important. The system gives them time to care.",ja:"18%の伸びは、しくみだけのおかげですか？／それだけではありません。しくみも助けになりますが、スタッフのケアも同じくらい大切です。しくみがケアする時間を生んでくれます。"},
   {q:"How many new patients did the clinic get?",a:"I don't have that number with me today. I'll check and send it to you by email.",ja:"新しい患者さんは何人でしたか？／今日はその数字を持っていません。確認してメールでお送りします。"},
   {q:"Can the system show these charts automatically?",a:"Yes. It shows sales, visits and returning patients on one screen every day.",ja:"しくみは、これらのグラフを自動で出せますか？／はい。売上・来院数・再来院を毎日1つの画面に出します。"}
  ],
  check:[
   "最初に「何のグラフか」と縦軸・横軸を言えたか",
   "from 〜 to と by を正しく使い分けたか（rose to と rose by のちがい）",
   "rise / fall / remain stable / peak をそれぞれ1回以上使えたか",
   "動きのあとに理由をひとこと言えたか",
   "1枚のスライドで言う数字を2〜3個にしぼれたか"
  ],
  slide:"グラフは線を1本か2本だけにし、言いたい点（山や上がった所）に丸をつけて、上に一言の結論（例：Returning patients +15 points）を書きましょう。"},
 {week:42, level:"B1+", length:"5分", title:"交渉につなげる提案",
  skill:"「もし〜してくだされば、〜します」の条件の形で、相手が話し合いに乗りやすい提案を5分で出せる。",
  lesson:[
   "今週は、プレゼンの最後を「交渉の入り口」にする練習です。提案のプレゼンは、ただ説明して終わるのではなく、「こういう条件なら、こうできます」と選べる形で出すと、相手は話し合いに入りやすくなります。",
   "条件を出す基本の形は If you could..., we would...（もし〜していただけるなら、私たちは〜します）です。could と would を使うと、押しつけない、やわらかい言い方になります。もう少しはっきり条件をつけたいときは、On the condition that...（〜という条件で）や As long as...（〜であれば）を使います。",
   "交渉では、最初から全部を出さないことも大切です。「まずは小さく試す（パイロット）」という案は、相手の心配を減らします。また、こちらが譲れること（期間・人数・支払いの時期など）と、譲れないこと（品質・安全）を、話す前に紙に書いて分けておきましょう。",
   "今週の手本は、インドのクリニックのグループに、おもてなし研修と予約のしくみを「2院で3か月だけ試す」形で提案する話です。期間・人数・値引きなどの条件は練習用の例です。"
  ],
  structure:[
   {en:"Their goal",ja:"相手の目標を確かめる"},
   {en:"Our proposal",ja:"こちらの提案"},
   {en:"Options with conditions",ja:"条件つきの選択肢"},
   {en:"What we need from you",ja:"相手にお願いすること"},
   {en:"Next step",ja:"次の一歩"}
  ],
  phrases:[
   {en:"If you could share your monthly data, we would prepare a clear report for you.",ja:"毎月のデータを共有していただけるなら、わかりやすい報告書をご用意します。",note:"If you could..., we would... の基本の形。"},
   {en:"If you could start with two clinics, we would reduce the fee.",ja:"2院から始めていただけるなら、料金を下げます。",note:"相手の小さな一歩と、こちらの得を組み合わせる。"},
   {en:"We can offer a discount on the condition that you sign up for six months.",ja:"6か月のお申し込みという条件で、値引きができます。",note:"on the condition that = 〜という条件で。"},
   {en:"As long as your staff can join the training, the results will be stronger.",ja:"スタッフの皆さんが研修に参加できれば、成果はもっと大きくなります。",note:"as long as = 〜であれば。やわらかい条件。"},
   {en:"Would you be open to a three-month trial?",ja:"3か月のお試しについて、ご検討いただけますか？",note:"相手に選ぶ余地を残す聞き方。"},
   {en:"What if we started small?",ja:"小さく始めてみるのはどうでしょう？",note:"What if + 過去形 で、気軽な提案になる。"},
   {en:"That's something we could be flexible on.",ja:"その点は、私たちも柔軟に考えられます。",note:"譲れることを伝える。"},
   {en:"I'm afraid we can't change the quality of the training.",ja:"申し訳ありませんが、研修の質は変えられません。",note:"譲れないことは、ていねいに、でもはっきり。"},
   {en:"Let me suggest two options.",ja:"2つの案をご提案します。",note:"選択肢があると、相手は「どちらか」で考えてくれる。"},
   {en:"Which option would work better for you?",ja:"どちらの案のほうが合いそうですか？",note:"提案の最後に、相手に選んでもらう。"}
  ],
  model:{title:"インドのクリニックへの「小さく始める」提案（5分）", time:"5分", note:"期間・人数・料金・値引きなどの数字や条件は練習用の例です。自分の数字に入れかえましょう。",
   lines:[
    {en:"Good morning, everyone. Thank you for meeting me again.",ja:"皆さん、おはようございます。また時間をとっていただき、ありがとうございます。"},
    {en:"Last time, you told me about your goal. You want more patients to come back, and you want to welcome guests from Japan.",ja:"前回、皆さんの目標を教えていただきました。もっと多くの患者さんに戻ってきてほしい、そして日本からのお客様を迎えたい、ということでした。"},
    {en:"Today I'd like to suggest a simple way to start, and I'd like to hear what you think.",ja:"今日は、始めるためのかんたんな方法をご提案し、皆さんのご意見をうかがいたいと思います。"},
    {en:"Let me start with our proposal. It has two parts: hospitality training and our booking system.",ja:"まず提案からお話しします。2つの部分があります。おもてなし研修と、予約のしくみです。"},
    {en:"The training teaches your staff how to welcome patients the Japanese way.",ja:"研修では、スタッフの皆さんに、日本式の患者さんの迎え方をお伝えします。"},
    {en:"For example, how to greet, how to explain a treatment, and how to follow up after a visit.",ja:"たとえば、あいさつのしかた、施術の説明のしかた、来院後のフォローのしかたです。"},
    {en:"The booking system helps you remember each patient and send a short message after each visit.",ja:"予約のしくみは、一人ひとりの患者さんを覚え、来院のあとに短いメッセージを送るのに役立ちます。"},
    {en:"In my own clinic in Japan, I check sales, visits and returning patients every day with this system.",ja:"日本の私の院では、このしくみで売上・来院数・再来院を毎日確認しています。"},
    {en:"Moving on to the options. I know you have eight clinics, and starting everywhere at once is a big step.",ja:"次に、選択肢に移ります。皆さんは8つの院をお持ちで、すべてで一度に始めるのは大きな一歩だと承知しています。"},
    {en:"So what if we started small? Let me suggest two options.",ja:"そこで、小さく始めてみるのはどうでしょうか。2つの案をご提案します。"},
    {en:"Option A is a three-month trial in two clinics. Option B is a six-month plan in all eight clinics.",ja:"A案は、2院で3か月のお試し。B案は、8院すべてで6か月のプランです。"},
    {en:"If you could start with two clinics, we would reduce the fee for the trial by 20%.",ja:"2院から始めていただけるなら、お試しの料金を20%下げます。"},
    {en:"And if the trial goes well, the fee you paid would count toward the full plan.",ja:"そしてお試しがうまくいけば、お支払いいただいた料金は、本番のプランの分に回します。"},
    {en:"For Option B, we can offer a discount on the condition that you sign up for six months.",ja:"B案については、6か月のお申し込みという条件で、値引きができます。"},
    {en:"That brings me to what we need from you. We need three things.",ja:"そこで、皆さんにお願いしたいことの話になります。3つあります。"},
    {en:"First, if you could choose one manager for the project, we would work closely with that person.",ja:"1つめ、このプロジェクトの担当の方を1人決めていただければ、その方と密に連携します。"},
    {en:"Second, as long as your staff can join two training days, the results will be much stronger.",ja:"2つめ、スタッフの皆さんが2日間の研修に参加できれば、成果はずっと大きくなります。"},
    {en:"Third, if you could share your monthly numbers, we would prepare a clear report every month.",ja:"3つめ、毎月の数字を共有していただけるなら、毎月わかりやすい報告書をご用意します。"},
    {en:"Now, some points are flexible. The start date is something we could be flexible on.",ja:"さて、柔軟に考えられる点もあります。開始日については、私たちも柔軟に考えられます。"},
    {en:"The training schedule is flexible too. We can train on weekdays or on weekends.",ja:"研修の日程も調整できます。平日でも週末でも研修できます。"},
    {en:"However, I'm afraid we can't change the quality of the training. I will lead the first sessions myself.",ja:"ただし、申し訳ありませんが、研修の質は変えられません。最初の回は私自身が担当します。"},
    {en:"I believe this is important. Good care depends on people, not only on systems.",ja:"これは大切だと考えています。よいケアは、しくみだけでなく人によって決まるからです。"},
    {en:"Let me give you an example of what a trial could look like.",ja:"お試しがどんな形になるか、例をお見せします。"},
    {en:"In month one, we train the staff and set up the system. In month two, we follow up every visit.",ja:"1か月めにスタッフ研修としくみの準備をします。2か月めは、すべての来院のあとにフォローします。"},
    {en:"In month three, we look at the numbers together and decide the next step.",ja:"3か月めに、一緒に数字を見て、次の一歩を決めます。"},
    {en:"If the numbers don't improve, you can simply stop. There is no long-term commitment.",ja:"数字がよくならなければ、そこでやめていただいてかまいません。長い契約にしばられることはありません。"},
    {en:"If the numbers do improve, we would plan the next step together, clinic by clinic.",ja:"数字がよくなれば、院ごとに、次の一歩を一緒に計画します。"},
    {en:"I'd also like to hear your ideas. You know your patients and your city much better than I do.",ja:"皆さんのお考えもぜひ聞かせてください。患者さんや街のことは、私よりずっとよくご存じですから。"},
    {en:"For example, you may want to change the timing of the messages, or add a message in Hindi.",ja:"たとえば、メッセージを送る時期を変えたい、ヒンディー語のメッセージを足したい、ということもあるでしょう。"},
    {en:"To conclude, we have two options. Option A is small and safe. Option B is bigger and gives you a better price.",ja:"まとめると、2つの案があります。A案は小さくて安心。B案は大きく、よりよい価格になります。"},
    {en:"In both options, I will be there to support your team.",ja:"どちらの案でも、私がチームを支えます。"},
    {en:"Would you be open to a three-month trial? Or would you prefer to start with all eight clinics?",ja:"3か月のお試しをご検討いただけますか？ それとも8院すべてで始めるほうがよいでしょうか？"},
    {en:"Which option would work better for you? I'm happy to discuss the details now.",ja:"どちらの案のほうが合いそうですか？ 今から細かい点をご相談できます。"},
    {en:"Thank you very much.",ja:"ありがとうございました。"}
   ]},
  task:"インドのクリニックのグループに、おもてなし研修と予約のしくみを「A案：小さく試す／B案：まとめて始める」の2案で5分で提案する。If you could..., we would... を3回以上使う。",
  taskEn:"Propose hospitality training and a booking system to a clinic group in India in 5 minutes. Offer two options (a small trial and a full plan), and use 'If you could..., we would...' at least three times.",
  qa:[
   {q:"Could you reduce the fee by 30% instead of 20%?",a:"I understand. If you could sign up for six months after the trial, we would consider a bigger discount.",ja:"20%ではなく30%下げられますか？／わかります。お試しのあと6か月お申し込みいただけるなら、もっと大きな値引きを考えます。"},
   {q:"Can our own trainers lead the training instead of you?",a:"I'm afraid I need to lead the first sessions. After that, your trainers could take over, and I would support them.",ja:"あなたではなく、私たちのトレーナーが研修をしてもいいですか？／申し訳ありませんが、最初の回は私が担当する必要があります。そのあとは皆さんのトレーナーに引き継ぎ、私が支えます。"},
   {q:"What happens if we stop after the trial?",a:"Then the project simply ends. You can keep the training materials, and there is no extra cost.",ja:"お試しのあとでやめたらどうなりますか？／そこでプロジェクトは終わりです。研修の資料はそのままお使いいただけ、追加の費用はかかりません。"},
   {q:"Can we start next month?",a:"That's something we could be flexible on. Let me check my schedule in India and confirm by Friday.",ja:"来月から始められますか？／その点は柔軟に考えられます。インドでの予定を確認して、金曜までにお知らせします。"}
  ],
  check:[
   "If you could..., we would... を3回以上、自然に使えたか",
   "on the condition that / as long as のどちらかを使えたか",
   "譲れること（日程など）と譲れないこと（質）を分けて言えたか",
   "2つの案を出し、最後に相手に選んでもらえたか",
   "押しつけるような言い方（You must...）をしていないか"
  ],
  slide:"A案とB案を左右に並べ、「期間・院の数・料金・お願いすること」を同じ順に書くと、相手が見くらべやすくなります。"},
 {week:43, level:"B2-", length:"5分", title:"価格と費用対効果を示す",
  skill:"値段を言うだけでなく、「何に投資して、いつ回収でき、どんな価値があるか」を数字で5分で説明できる。",
  lesson:[
   "今週は、お金の話をプレゼンで伝える練習です。値段をいきなり言うと、聞き手は「高い」とだけ感じてしまいます。順番は、①相手の今の困りごと ②こちらの提案 ③かかる費用（投資）④もどってくるお金（回収）⑤お金以外の価値、です。この順なら、値段は「コスト」ではなく「投資」として聞こえます。",
   "使う言葉は、investment（投資）、one-time fee（最初に1回だけの料金）、monthly fee（毎月の料金）、pay back / break even（元がとれる）、return on investment（投資の見返り）、value for money（払う価値がある）です。The investment will pay for itself in five months.（5か月で元がとれます）は、とても強い一文です。",
   "数字は、計算の道すじを見せるのがコツです。「1回の来院で1,500ルピー × 1か月に40回ふえる = 6万ルピー」のように、かけ算を1つずつ言うと信用されます。インドでは 1 lakh = 10万、1 crore = 1,000万 です。150,000 rupees は「1.5 lakh rupees」とも言われるので、両方の言い方に慣れておきましょう。",
   "最後に、お金で表せない価値（スタッフの自信、お客様の満足、評判）も1つ添えます。今週の手本は、インドのウェルネスセンターに予約のしくみと研修の費用対効果を示す話です。金額と計算はすべて練習用の例です。"
  ],
  structure:[
   {en:"The problem and its cost",ja:"今の困りごとと、その損"},
   {en:"The investment",ja:"かかる費用（投資）"},
   {en:"The return",ja:"もどってくるお金（回収）"},
   {en:"Value beyond money",ja:"お金以外の価値"},
   {en:"Summary and next step",ja:"まとめと次の一歩"}
  ],
  phrases:[
   {en:"Let's look at this as an investment, not a cost.",ja:"これを費用ではなく、投資として見てみましょう。",note:"値段を出す前の、考え方の切りかえ。"},
   {en:"There is a one-time set-up fee of 150,000 rupees.",ja:"最初に1回だけ、15万ルピーの導入費がかかります。",note:"one-time と monthly を分けて言う。"},
   {en:"After that, the monthly fee is 30,000 rupees.",ja:"そのあとは、毎月3万ルピーです。",note:"after that で順番をはっきり。"},
   {en:"Let me show you how I calculated this.",ja:"どう計算したかをお見せします。",note:"計算の道すじを見せると信用される。"},
   {en:"That's an extra 60,000 rupees a month.",ja:"これで毎月6万ルピーが上乗せされます。",note:"a month = 1か月あたり。"},
   {en:"The investment will pay for itself in about five months.",ja:"この投資は、約5か月で元がとれます。",note:"費用対効果をひとことで言う決め文。"},
   {en:"After that, it's pure profit for your business.",ja:"そのあとは、まるごと皆さんの利益になります。",note:"回収後の得をはっきり示す。"},
   {en:"In other words, it's good value for money.",ja:"言いかえれば、払う価値が十分にあります。",note:"in other words でまとめ直す。"},
   {en:"There is also value that numbers can't show.",ja:"数字では見えない価値もあります。",note:"お金以外の価値に移る合図。"},
   {en:"These figures are an estimate, so let's check them together.",ja:"これらは見込みの数字なので、一緒に確かめましょう。",note:"約束しすぎない、正直な一言。"}
  ],
  model:{title:"予約のしくみと研修の費用対効果（5分）", time:"5分", note:"金額・回数・期間などの数字は練習用の例です。自分の数字に入れかえましょう。",
   lines:[
    {en:"Good afternoon, everyone. Today I'd like to talk about money: what this project costs, and what it gives back.",ja:"皆さん、こんにちは。今日はお金のお話をします。このプロジェクトにいくらかかり、何がもどってくるかです。"},
    {en:"Let's look at this as an investment, not a cost.",ja:"これを費用ではなく、投資として見てみましょう。"},
    {en:"My talk has three parts: the problem, the investment, and the return.",ja:"話は3つです。困りごと、投資、そして回収です。"},
    {en:"Let me start with the problem. Last month you told me that many patients come only once.",ja:"まず困りごとから。先月、多くの患者さんが1回しか来ないとうかがいました。"},
    {en:"They feel better after one visit, but the pain often comes back later.",ja:"1回の来院で楽になりますが、あとで痛みがもどることが多いのです。"},
    {en:"This is a loss for the patient and a loss for your centre.",ja:"これは患者さんにとっても、センターにとっても損失です。"},
    {en:"Finding a new patient usually takes more time and money than keeping a patient you already have.",ja:"新しい患者さんを見つけるには、今いる患者さんに続けてもらうより、たいてい時間もお金もかかります。"},
    {en:"So every patient who doesn't come back is a cost you can't see on paper.",ja:"ですから、もどってこない患者さん一人ひとりが、紙の上には見えない損なのです。"},
    {en:"In my own clinic in Japan, I check returning patients every day, because this number tells me a lot.",ja:"日本の私の院では、毎日再来院を確認しています。この数字が多くを教えてくれるからです。"},
    {en:"Moving on to the investment. There is a one-time set-up fee of 150,000 rupees, or one and a half lakh.",ja:"次に投資の話です。最初に1回だけ、15万ルピー、つまり1.5ラークの導入費がかかります。"},
    {en:"This includes setting up the booking system and two days of hospitality training for your staff.",ja:"ここには、予約のしくみの準備と、スタッフの皆さんへの2日間のおもてなし研修が含まれます。"},
    {en:"After that, the monthly fee is 30,000 rupees. It covers the system, monthly reports and online support.",ja:"そのあとは毎月3万ルピーです。しくみ、毎月の報告、オンラインのサポートが含まれます。"},
    {en:"That brings me to the return. Let me show you how I calculated this.",ja:"そこで回収の話になります。どう計算したかをお見せします。"},
    {en:"First, the average payment for one visit at your centre is about 1,500 rupees.",ja:"まず、センターでの1回の来院の平均のお支払いは、約1,500ルピーです。"},
    {en:"Second, with reminder messages and better follow-up, we expect about 40 more return visits a month.",ja:"次に、お知らせのメッセージとよりよいフォローで、月に約40回の再来院がふえると見込んでいます。"},
    {en:"So, 1,500 rupees times 40 visits is 60,000 rupees. That's an extra 60,000 rupees a month.",ja:"つまり、1,500ルピー × 40回で6万ルピー。毎月6万ルピーが上乗せされます。"},
    {en:"Now, take away the monthly fee of 30,000 rupees. You still keep 30,000 rupees a month.",ja:"ここから毎月の料金3万ルピーを引きます。それでも毎月3万ルピーが残ります。"},
    {en:"The set-up fee was 150,000 rupees. 150,000 divided by 30,000 is five.",ja:"導入費は15万ルピーでした。15万を3万で割ると5です。"},
    {en:"So the investment will pay for itself in about five months.",ja:"ですから、この投資は約5か月で元がとれます。"},
    {en:"After that, it's pure profit for your business. Over the first year, that's about 210,000 rupees more.",ja:"そのあとは、まるごと皆さんの利益になります。最初の1年で、約21万ルピーのプラスです。"},
    {en:"Of course, these figures are an estimate, so let's check them together with your real numbers.",ja:"もちろん、これらは見込みの数字なので、皆さんの実際の数字で一緒に確かめましょう。"},
    {en:"If your average payment is higher, the payback will be even faster.",ja:"平均のお支払いがもっと高ければ、回収はさらに早くなります。"},
    {en:"If it's lower, the payback will take a little longer. I want you to see both sides clearly.",ja:"低ければ、回収にもう少し時間がかかります。両方の面をはっきり見ていただきたいのです。"},
    {en:"Let me compare this with another option. Some centres spend money on advertising to find new patients.",ja:"別の方法とくらべてみます。新しい患者さんを見つけるために、広告にお金をかけるセンターもあります。"},
    {en:"Advertising can work, but the result stops when the money stops.",ja:"広告も効果はありますが、お金を止めると効果も止まります。"},
    {en:"Better follow-up is different. The habits stay with your staff, even after the project ends.",ja:"よりよいフォローはちがいます。プロジェクトが終わっても、習慣はスタッフの中に残ります。"},
    {en:"There is also value that numbers can't show. Let me mention three things.",ja:"数字では見えない価値もあります。3つ挙げます。"},
    {en:"First, your staff will feel more confident when they greet and explain.",ja:"1つめ、スタッフの皆さんが、あいさつや説明をするときにもっと自信を持てます。"},
    {en:"Second, patients will feel that someone remembers them. That feeling builds trust.",ja:"2つめ、患者さんは「覚えてもらえている」と感じます。その気持ちが信頼を生みます。"},
    {en:"Third, guests from Japan will feel at home. Good reviews from them can bring new guests.",ja:"3つめ、日本からのお客様がくつろげます。その方々のよい口コミが、新しいお客様を呼びます。"},
    {en:"None of these appear in the calculation I just showed you. But in my experience, they matter just as much.",ja:"どれも、今お見せした計算には入っていません。でも私の経験では、同じくらい大切です。"},
    {en:"A team that feels proud of its care keeps improving, month after month, without being told.",ja:"自分たちのケアに誇りを持つチームは、言われなくても、月ごとによくなり続けます。"},
    {en:"In other words, it's good value for money, both in rupees and in reputation.",ja:"言いかえれば、ルピーの面でも評判の面でも、払う価値が十分にあります。"},
    {en:"To conclude, let me sum up the numbers.",ja:"まとめとして、数字をくり返します。"},
    {en:"You invest 150,000 rupees once and 30,000 rupees a month.",ja:"1回だけ15万ルピーと、毎月3万ルピーを投資します。"},
    {en:"You get back about 60,000 rupees a month, so you break even in about five months.",ja:"毎月約6万ルピーがもどるので、約5か月で元がとれます。"},
    {en:"And you get happier patients and a stronger team.",ja:"そして、患者さんの満足と、より強いチームが手に入ります。"},
    {en:"As a next step, could you share last year's visit numbers? Then I can make this estimate more accurate.",ja:"次の一歩として、昨年の来院数を共有していただけますか？ そうすれば、この見込みをもっと正確にできます。"},
    {en:"Thank you very much. I'm happy to answer any questions about the numbers.",ja:"ありがとうございました。数字についてのご質問にお答えします。"}
   ]},
  task:"インドのウェルネスセンターの経営者に、予約のしくみと研修の「投資・回収・お金以外の価値」を、計算の道すじを見せながら5分で説明する。",
  taskEn:"Explain the cost and return of a booking system and hospitality training to the owners of a wellness centre in India in 5 minutes. Show your calculation step by step, and say when they will break even.",
  qa:[
   {q:"What if we only get 20 more visits a month, not 40?",a:"Good question. Then you would earn 30,000 rupees a month, which covers the monthly fee. The payback would take longer, so we would review the plan after three months.",ja:"月に40回ではなく20回しかふえなかったら？／よい質問です。その場合は月3万ルピーで、毎月の料金はまかなえます。回収には時間がかかるので、3か月後に計画を見直します。"},
   {q:"Is the set-up fee negotiable?",a:"We could be flexible if you start with more than one centre. Let's discuss the details after the meeting.",ja:"導入費は交渉できますか？／複数のセンターで始めていただけるなら、柔軟に考えられます。会議のあとで細かくご相談しましょう。"},
   {q:"Are there any hidden costs?",a:"No. The monthly fee includes the system, reports and online support. If you want extra training days, I'll give you a clear quote first.",ja:"隠れた費用はありますか？／ありません。毎月の料金に、しくみ・報告・オンラインのサポートが含まれます。研修の日を追加したい場合は、先にはっきりしたお見積もりをお出しします。"},
   {q:"How sure are you about the five months?",a:"It's an estimate, not a promise. That's why I'd like to check it with your real numbers before we start.",ja:"5か月というのは、どのくらい確かですか？／見込みであって、約束ではありません。だからこそ、始める前に実際の数字で確かめたいのです。"}
  ],
  check:[
   "値段の前に、相手の困りごとと「投資」という考え方を出せたか",
   "one-time fee と monthly fee を分けて言えたか",
   "計算の道すじ（かけ算・引き算・割り算）を声に出して見せられたか",
   "pay for itself / break even / value for money を使えたか",
   "見込みの数字を「約束」のように言いすぎていないか"
  ],
  slide:"左に「投資（1回・毎月）」、右に「回収（毎月・回収までの月数）」を大きな数字で並べ、下にお金以外の価値を3つ、小さく書きましょう。"},
 {week:44, level:"B2-", length:"6分", title:"提携の提案プレゼン",
  skill:"自分の強みではなく「相手が得られること」を中心にして、提携の提案を6分で語れる。",
  lesson:[
   "今週は、提携（パートナーシップ）を提案するプレゼンです。いちばん大切なのは、主語を「私たち」から「あなた」に変えることです。We have a great system.（私たちにはよいしくみがあります）より、This would allow you to see every patient's history on one screen.（これで、すべての患者さんの記録を1つの画面で見られるようになります）の方が、ずっと相手の心に届きます。",
   "This would allow you to...（これで〜できるようになります）と We believe...（〜と考えています）は、提携の話の柱です。would を使うと「まだ決まっていないけれど、もし一緒にやれば」という、ていねいな未来の言い方になります。We believe... は、自分の考えを押しつけずに、はっきり伝える言い方です。",
   "提携の提案は、①相手の目標 ②なぜ私たちなのか（強みは短く、本当のことだけ）③相手が得られること3つ ④お互いの役割 ⑤最初の一歩、の順が基本です。強みを話すときは、経歴を大きく見せないこと。本当の経験を、短く、具体的に言うほうが信頼されます。",
   "今週の手本は、インドのホテル・ウェルネスのグループに「日本の健康とケアのノウハウ」「おもてなし」「予約と顧客管理のしくみ」「日本酒の夜」をまとめて提携として提案する話です。相手の会社の様子や期間は練習用の例です。"
  ],
  structure:[
   {en:"Their vision",ja:"相手の目指すもの"},
   {en:"Why us (short and true)",ja:"なぜ私たちか（短く、本当のことだけ）"},
   {en:"Three benefits for you",ja:"相手が得られること3つ"},
   {en:"Roles in the partnership",ja:"お互いの役割"},
   {en:"The first step",ja:"最初の一歩"}
  ],
  phrases:[
   {en:"We believe this partnership would benefit both of us.",ja:"この提携は、私たち双方のためになると考えています。",note:"提案の中心をひとことで。"},
   {en:"This would allow you to offer something your competitors can't.",ja:"これで、競合にはできないものをご提供できるようになります。",note:"主語は this、得をするのは you。"},
   {en:"What you would gain is a stronger relationship with your guests.",ja:"皆さんが得られるのは、お客様とのより強い関係です。",note:"What you would gain is... で得を強調。"},
   {en:"We understand that your goal is to attract more guests from Japan.",ja:"皆さんの目標は、日本からのお客様をもっと迎えることだと理解しています。",note:"最初に相手の目標を言葉にする。"},
   {en:"Why us? Let me be brief.",ja:"なぜ私たちなのか。手短にお話しします。",note:"自分の話は短く、という合図。"},
   {en:"We bring practical experience, not just theory.",ja:"私たちがお持ちするのは、理論だけでなく現場の経験です。",note:"強みは本当のことだけを短く。"},
   {en:"Your team would focus on daily service, and we would support the training and the system.",ja:"皆さんのチームは日々のサービスに集中し、私たちは研修としくみを支えます。",note:"役割を分けて言うと安心される。"},
   {en:"We see this as a long-term partnership, not a one-time project.",ja:"これを1回きりの仕事ではなく、長いおつきあいと考えています。",note:"関係を大切にする姿勢を見せる。"},
   {en:"Together, we could create a new kind of wellness experience in India.",ja:"一緒に、インドで新しい形のウェルネス体験をつくれます。",note:"together で一緒に描く未来を示す。"},
   {en:"As a first step, we suggest a small pilot at one of your hotels.",ja:"最初の一歩として、ホテルの1つで小さな試行をご提案します。",note:"大きな提携も、最初の一歩は小さく。"}
  ],
  model:{title:"インドのホテル・ウェルネスのグループへの提携提案（6分）", time:"6分", note:"相手のグループの様子・期間・規模は練習用の例です。自分の場面に入れかえましょう。",
   lines:[
    {en:"Good morning, everyone. Thank you for giving me this time today.",ja:"皆さん、おはようございます。本日はお時間をいただき、ありがとうございます。"},
    {en:"Today I'd like to propose a partnership between your group and my team in Japan.",ja:"今日は、皆さんのグループと日本の私のチームとの提携をご提案します。"},
    {en:"I'll talk about your vision, why we could help, what you would gain, and how we could start.",ja:"皆さんの目指すもの、なぜ私たちがお役に立てるか、皆さんが得られること、そしてどう始めるかをお話しします。"},
    {en:"Let me start with your vision. We understand that your goal is to attract more guests from Japan.",ja:"まず皆さんの目指すものから。皆さんの目標は、日本からのお客様をもっと迎えることだと理解しています。"},
    {en:"You also want to offer wellness services that feel special, not just another spa menu.",ja:"また、ありきたりのスパのメニューではない、特別だと感じられるウェルネスのサービスを提供したいとお考えです。"},
    {en:"And many of your Indian guests love Japan. They are curious about Japanese food, culture and care.",ja:"そして、インドのお客様の多くが日本好きです。日本の食べ物、文化、ケアに興味を持っています。"},
    {en:"So, why us? Let me be brief.",ja:"では、なぜ私たちなのか。手短にお話しします。"},
    {en:"I'm a licensed acupuncturist and judo therapist. I run a clinic in Ehime, Japan, with a team of four staff.",ja:"私は鍼灸師・柔道整復師です。日本の愛媛で、スタッフ4名のチームと院を営んでいます。"},
    {en:"Before that, I worked as an athletic trainer for school, corporate and professional sports teams.",ja:"その前は、学校・実業団・プロのスポーツチームでアスレティックトレーナーをしていました。"},
    {en:"I also built a booking and customer management system for my clinic. Now partner clinics use it too.",ja:"また、院のために予約と顧客管理のしくみを作りました。今は提携院も使っています。"},
    {en:"And my family runs a sake shop that was founded in 1957. I'm in charge of international affairs there.",ja:"そして、家族が1957年創業の酒店を営んでいます。私はそこで国際担当をしています。"},
    {en:"In short, we bring practical experience, not just theory.",ja:"つまり、私たちがお持ちするのは、理論だけでなく現場の経験です。"},
    {en:"Moving on to the most important part: what you would gain. I see three benefits for you.",ja:"いちばん大切なところ、皆さんが得られることに移ります。3つあると考えています。"},
    {en:"The first benefit is Japanese health and care know-how.",ja:"1つめは、日本の健康とケアのノウハウです。"},
    {en:"We would teach your therapists simple Japanese care for tired shoulders, backs and legs after a long flight.",ja:"長いフライトのあとの、疲れた肩・背中・脚のための、日本のかんたんなケアをセラピストの皆さんにお伝えします。"},
    {en:"Let me give you an example. A guest arrives after a ten-hour flight with a stiff neck and swollen legs.",ja:"例を挙げます。10時間のフライトのあと、首がこって脚がむくんだお客様が到着したとします。"},
    {en:"Your therapist checks the guest's posture, explains the care in simple words, and gives one easy stretch for the room.",ja:"セラピストが姿勢を確かめ、ケアをかんたんな言葉で説明し、部屋でできるかんたんなストレッチを1つお伝えします。"},
    {en:"The next morning, the front desk asks how the guest slept. That small question is part of the care.",ja:"翌朝、フロントがよく眠れたかをたずねます。その小さな問いかけも、ケアの一部です。"},
    {en:"This would allow you to offer a menu that your competitors can't easily copy.",ja:"これで、競合がかんたんにはまねできないメニューをご提供できるようになります。"},
    {en:"The second benefit is real omotenashi.",ja:"2つめは、本物のおもてなしです。"},
    {en:"We would train your front desk and service staff to notice what guests need before they ask.",ja:"フロントやサービスのスタッフの皆さんに、お客様が言う前に必要なことに気づく力をお伝えします。"},
    {en:"This would allow you to make Japanese guests feel at home, and Indian guests feel truly special.",ja:"これで、日本のお客様にはくつろいでいただき、インドのお客様には本当に特別だと感じていただけます。"},
    {en:"The third benefit is a simple booking and customer system.",ja:"3つめは、かんたんな予約と顧客のしくみです。"},
    {en:"It would allow you to remember each guest's preferences and contact them after their stay.",ja:"これで、一人ひとりのお客様の好みを覚え、滞在のあとにご連絡できるようになります。"},
    {en:"What you would gain is a stronger relationship with your guests, and more guests who come back.",ja:"皆さんが得られるのは、お客様とのより強い関係と、また来てくださるお客様の増加です。"},
    {en:"And there is one more idea. We could host a Japanese evening with sake for your guests.",ja:"そして、もう1つ案があります。お客様のために、日本酒を楽しむ日本の夜を開くことができます。"},
    {en:"We believe a good sake, served with a short story about its region, makes guests remember the evening.",ja:"産地の短い物語とともに出すよい日本酒は、お客様の心にその夜を残すと考えています。"},
    {en:"That brings me to the roles in this partnership.",ja:"そこで、この提携でのお互いの役割の話になります。"},
    {en:"Your team would focus on daily service, and we would support the training and the system.",ja:"皆さんのチームは日々のサービスに集中し、私たちは研修としくみを支えます。"},
    {en:"Your managers know your guests and your city. We know Japanese care and hospitality.",ja:"マネージャーの皆さんは、お客様と街のことをご存じです。私たちは日本のケアとおもてなしを知っています。"},
    {en:"We believe the best results come when both sides share what they know.",ja:"いちばんよい結果は、お互いが知っていることを持ち寄ったときに生まれると考えています。"},
    {en:"We see this as a long-term partnership, not a one-time project.",ja:"これを1回きりの仕事ではなく、長いおつきあいと考えています。"},
    {en:"So, how could we start? As a first step, we suggest a small pilot at one of your hotels.",ja:"では、どう始めるか。最初の一歩として、ホテルの1つで小さな試行をご提案します。"},
    {en:"For three months, we would train the staff, set up the system and hold one Japanese evening.",ja:"3か月間で、スタッフ研修、しくみの準備、日本の夜を1回行います。"},
    {en:"Then we would look at guest feedback together and decide whether to grow the partnership.",ja:"そのあと、お客様の声を一緒に見て、提携を広げるかどうかを決めます。"},
    {en:"We would measure a few simple things: guest reviews, repeat bookings, and how confident your staff feel.",ja:"いくつかのかんたんなことを測ります。お客様の評価、リピートの予約、そしてスタッフの皆さんの自信です。"},
    {en:"If the pilot works well, the next step could be to bring the program to your other hotels.",ja:"試行がうまくいけば、次の一歩として、ほかのホテルにも広げることができます。"},
    {en:"To conclude, we believe this partnership would benefit both of us.",ja:"まとめると、この提携は私たち双方のためになると考えています。"},
    {en:"You would gain Japanese care, real omotenashi and a closer relationship with your guests.",ja:"皆さんは、日本のケア、本物のおもてなし、そしてお客様とのより近い関係を得られます。"},
    {en:"Together, we could create a new kind of wellness experience in India.",ja:"一緒に、インドで新しい形のウェルネス体験をつくれます。"},
    {en:"Thank you very much. I'd love to hear your thoughts and questions.",ja:"ありがとうございました。皆さんのお考えとご質問をぜひお聞かせください。"}
   ]},
  task:"インドのホテルかウェルネスのグループに、日本のケアのノウハウ・おもてなし・予約のしくみ・日本酒をまとめた提携を、相手の得を中心に6分で提案する。This would allow you to... を3回以上使う。",
  taskEn:"Propose a partnership to a hotel or wellness group in India in 6 minutes. Focus on what they would gain, and use 'This would allow you to...' and 'We believe...' several times.",
  qa:[
   {q:"What makes your care different from the massage we already offer?",a:"Our care comes from clinical work with injuries and sports. We focus on posture and recovery, and we explain each step to the guest.",ja:"私たちが今出しているマッサージと、あなたのケアは何がちがいますか？／私たちのケアは、けがやスポーツの臨床の仕事から来ています。姿勢と回復に重点を置き、一つひとつの手順をお客様に説明します。"},
   {q:"Who would actually train our staff?",a:"I would lead the training myself, at least at the start. Later, we could train one of your staff to become an in-house trainer.",ja:"実際に誰がスタッフを研修するのですか？／少なくとも最初は、私自身が研修を担当します。あとで、皆さんのスタッフの方を社内のトレーナーとして育てることもできます。"},
   {q:"Can we import the sake directly from your shop?",a:"We believe that's possible, but import rules and licences need to be checked first. I'll look into the details and get back to you.",ja:"あなたの店から日本酒を直接輸入できますか？／できると考えていますが、先に輸入のきまりと許可を確かめる必要があります。くわしく調べてご連絡します。"},
   {q:"Why should we choose a small clinic owner instead of a big company?",a:"Because I work in care every day. I can't promise the size of a big company, but I can promise full effort and real experience.",ja:"大きな会社ではなく、小さな院の院長を選ぶ理由は何ですか？／私は毎日ケアの現場にいるからです。大きな会社の規模はお約束できませんが、全力と本物の経験はお約束できます。"}
  ],
  check:[
   "主語を we より you / this にして、相手の得を中心に話せたか",
   "This would allow you to... と We believe... を合わせて4回以上使えたか",
   "自分の強みを短く、本当のことだけで話せたか",
   "お互いの役割を分けて言えたか",
   "最後に「小さな最初の一歩」を出せたか"
  ],
  slide:"「皆さんが得られること」のスライドは、3つの得をアイコンと短い見出し（Japanese care / Omotenashi / Guest system）だけで見せ、説明は口で話しましょう。"},
 {week:45, level:"B2-", length:"6分", title:"条件と契約の要点をまとめて示す",
  skill:"契約の大事な点（主な条件・お互いの責任・日程）を、聞き手がまちがえないように整理して6分で伝え、確認できる。",
  lesson:[
   "今週は、契約の前に「主な条件」をプレゼンでまとめて見せる練習です。契約書は長くてむずかしいので、サインの前に要点を一緒に確かめておくと、あとの行きちがいを防げます。順番は、①Key terms（主な条件：期間・料金・支払い）②Responsibilities（お互いの責任）③Timeline（日程）④まだ決まっていない点、が基本です。",
   "契約の英語には決まった言葉があります。shall / will は「〜する（義務）」、may は「〜してもよい」です。プレゼンでは、むずかしい shall は使わず、Your team will... / We will... / You may... と言いかえるとわかりやすくなります。また、payment within 30 days（30日以内の支払い）、notice（事前の知らせ）、confidential（ひみつにする）なども覚えましょう。",
   "要点を話すときは、1つ言うごとに確認するのがコツです。Is that correct?（それで合っていますか？）、Just to confirm...（念のため確認ですが）、Does everyone agree with this point?（この点は皆さんよろしいですか？）を使います。日本人は「わかったつもり」で先に進みがちですが、英語の場では、確認するのはていねいなことです。",
   "なお、本当の契約では、最後は必ず専門家（弁護士など）に書面を確かめてもらいましょう。今週の手本は、インドのホテルとの提携の主な条件をまとめて伝える話です。期間・金額・日数などはすべて練習用の例です。"
  ],
  structure:[
   {en:"Purpose of this summary",ja:"このまとめの目的"},
   {en:"Key terms",ja:"主な条件（期間・料金・支払い）"},
   {en:"Responsibilities",ja:"お互いの責任"},
   {en:"Timeline",ja:"日程"},
   {en:"Open points and confirmation",ja:"まだ決まっていない点と確認"}
  ],
  phrases:[
   {en:"Before we sign, I'd like to go through the key terms together.",ja:"サインの前に、主な条件を一緒に確認したいと思います。",note:"まとめの目的を最初に言う。"},
   {en:"The agreement will run for twelve months.",ja:"契約の期間は12か月です。",note:"run for = 〜の期間続く。"},
   {en:"Payment will be made within 30 days of each invoice.",ja:"支払いは、それぞれの請求書から30日以内に行います。",note:"within 〜 days of... = 〜から〜日以内。"},
   {en:"Our responsibility is to provide the training and the system.",ja:"私たちの責任は、研修としくみを提供することです。",note:"responsibility は「役目・責任」。"},
   {en:"Your team will be responsible for daily operations.",ja:"皆さんのチームは、日々の運営を担当します。",note:"be responsible for... = 〜を担当する。"},
   {en:"Either side may end the agreement with 60 days' notice.",ja:"どちらの側も、60日前に知らせれば契約を終了できます。",note:"may =「〜してもよい」。notice = 事前の知らせ。"},
   {en:"All guest data will be kept confidential.",ja:"お客様のデータは、すべて秘密として扱います。",note:"データの扱いは必ず言葉にする。"},
   {en:"Just to confirm, the pilot starts on the first of April. Is that correct?",ja:"念のため確認ですが、試行は4月1日開始で合っていますか？",note:"1つ言うごとに確認する。"},
   {en:"There is one point we still need to agree on.",ja:"まだ合意が必要な点が1つあります。",note:"決まっていない点は、かくさず出す。"},
   {en:"We will send you the final version of the contract by Friday.",ja:"金曜までに、契約書の最終版をお送りします。",note:"次の動きを日付つきで言う。"}
  ],
  model:{title:"インドのホテルとの提携：主な条件のまとめ（6分）", time:"6分", note:"期間・金額・日数・日付などの数字や条件は練習用の例です。自分の内容に入れかえましょう。本当の契約は、専門家に書面を確かめてもらいましょう。",
   lines:[
    {en:"Good afternoon, everyone. Thank you for all your work on this partnership over the last few weeks.",ja:"皆さん、こんにちは。ここ数週間、この提携のためにご尽力いただき、ありがとうございます。"},
    {en:"Before we sign, I'd like to go through the key terms together.",ja:"サインの前に、主な条件を一緒に確認したいと思います。"},
    {en:"The contract is long, so I'll focus on the points that matter most in daily work.",ja:"契約書は長いので、日々の仕事でいちばん大事な点にしぼってお話しします。"},
    {en:"I'll cover three areas: the key terms, our responsibilities, and the timeline. Then we'll look at one open point.",ja:"3つの分野をお話しします。主な条件、お互いの責任、そして日程です。そのあと、まだ決まっていない点を1つ見ます。"},
    {en:"Please stop me at any time if something is not clear.",ja:"わかりにくいところがあれば、いつでも止めてください。"},
    {en:"Let me start with the key terms. First, the agreement will run for twelve months.",ja:"まず主な条件から。1つめ、契約の期間は12か月です。"},
    {en:"It begins with a three-month pilot at your hotel in Bengaluru.",ja:"ベンガルールのホテルでの3か月の試行から始まります。"},
    {en:"After the pilot, we will review the results together and decide whether to include your other hotels.",ja:"試行のあと、一緒に結果を見直し、ほかのホテルを加えるかどうかを決めます。"},
    {en:"Second, the fees. There is a one-time set-up fee, and then a monthly fee for the system and support.",ja:"2つめ、料金です。最初に1回の導入費があり、そのあとは、しくみとサポートの毎月の料金です。"},
    {en:"Training days in India are charged separately, and travel costs are included in that daily fee.",ja:"インドでの研修の日は別料金で、交通費はその1日の料金に含まれます。"},
    {en:"Third, payment. Payment will be made within 30 days of each invoice, by bank transfer.",ja:"3つめ、支払いです。支払いは、それぞれの請求書から30日以内に、銀行振込で行います。"},
    {en:"Just to confirm, all amounts are in Indian rupees. Is that correct?",ja:"念のため確認ですが、金額はすべてインドルピーですね。合っていますか？"},
    {en:"Thank you. Fourth, ending the agreement. Either side may end the agreement with 60 days' notice.",ja:"ありがとうございます。4つめ、契約の終了です。どちらの側も、60日前に知らせれば契約を終了できます。"},
    {en:"We think this is fair. Nobody should feel trapped in a partnership.",ja:"これは公平だと考えています。誰も、提携にしばられていると感じるべきではありません。"},
    {en:"Moving on to responsibilities. This part is very important for daily work.",ja:"次に、お互いの責任に移ります。ここは日々の仕事にとってとても大切です。"},
    {en:"Our responsibility is to provide the training, the booking system and monthly reports.",ja:"私たちの責任は、研修、予約のしくみ、毎月の報告を提供することです。"},
    {en:"We will also answer your staff's questions online within one working day.",ja:"また、スタッフの皆さんからのご質問に、オンラインで1営業日以内にお答えします。"},
    {en:"Your team will be responsible for daily operations, such as bookings, guest service and therapy sessions.",ja:"皆さんのチームは、予約、お客様へのサービス、セラピーの施術など、日々の運営を担当します。"},
    {en:"You will also choose one project manager. That person will be our main contact.",ja:"また、プロジェクトの担当者を1人決めていただきます。その方が、私たちの主な窓口になります。"},
    {en:"Let me also be clear about what we will not do. We will not hire or manage your staff.",ja:"私たちがしないことも、はっきりさせておきます。皆さんのスタッフを雇ったり、管理したりはしません。"},
    {en:"And we will not give medical treatment to your guests. Our role is training and support.",ja:"また、お客様に医療としての治療はしません。私たちの役目は、研修とサポートです。"},
    {en:"I think it's important to say this now, so that there are no surprises later.",ja:"あとで驚くことがないように、今これを言っておくことが大切だと思います。"},
    {en:"Now, an important point about data. All guest data will be kept confidential.",ja:"さて、データについて大切な点です。お客様のデータは、すべて秘密として扱います。"},
    {en:"The data belongs to your hotel. We will only use it to prepare your reports.",ja:"データは皆さんのホテルのものです。私たちは、報告書を作るためだけに使います。"},
    {en:"Does everyone agree with this point?",ja:"この点は、皆さんよろしいでしょうか？"},
    {en:"Good. That brings me to the timeline.",ja:"ありがとうございます。そこで、日程の話になります。"},
    {en:"Just to confirm, the pilot starts on the first of April. Is that correct?",ja:"念のため確認ですが、試行は4月1日開始で合っていますか？"},
    {en:"In March, before the start, we will set up the system and translate the guest messages.",ja:"開始前の3月に、しくみを準備し、お客様へのメッセージを翻訳します。"},
    {en:"In the first two weeks of April, I will visit Bengaluru and lead two training days.",ja:"4月の最初の2週間に、私がベンガルールにうかがい、2日間の研修を担当します。"},
    {en:"In May, we will hold the first Japanese evening for your guests.",ja:"5月に、お客様のための最初の日本の夜を開きます。"},
    {en:"At the end of June, we will meet to review the pilot results together.",ja:"6月末に、試行の結果を一緒に見直す会議を開きます。"},
    {en:"At that meeting, we will look at guest reviews, repeat bookings and feedback from your staff.",ja:"その会議では、お客様の評価、リピートの予約、スタッフの皆さんの声を見ます。"},
    {en:"Then we will decide together whether to continue with one hotel or to expand.",ja:"そのうえで、1つのホテルで続けるか、広げるかを一緒に決めます。"},
    {en:"So, in short: set-up in March, training in April, the event in May, and the review in June.",ja:"つまり、3月に準備、4月に研修、5月にイベント、6月に見直しです。"},
    {en:"Now, there is one point we still need to agree on: the language of the guest messages.",ja:"さて、まだ合意が必要な点が1つあります。お客様へのメッセージの言語です。"},
    {en:"We suggest English and Japanese. You mentioned that Hindi could also be useful for some guests.",ja:"私たちは英語と日本語をご提案しています。一部のお客様にはヒンディー語も役立つとおっしゃっていました。"},
    {en:"If you could prepare the Hindi text, we would add it to the system at no extra cost.",ja:"ヒンディー語の文を用意していただけるなら、追加の費用なしでしくみに入れます。"},
    {en:"Could we decide this point by the end of this week?",ja:"この点を、今週中に決めていただけますか？"},
    {en:"To conclude, let me sum up. The agreement runs for twelve months, starting with a three-month pilot.",ja:"まとめます。契約は12か月で、3か月の試行から始まります。"},
    {en:"Payment is within 30 days, and either side may end it with 60 days' notice.",ja:"支払いは30日以内で、どちらの側も60日前の知らせで終了できます。"},
    {en:"We provide training, the system and reports. Your team runs daily operations, and the data stays yours.",ja:"私たちは研修、しくみ、報告を提供します。皆さんのチームは日々の運営を行い、データは皆さんのものです。"},
    {en:"Of course, both sides will ask their legal advisers to check the final contract.",ja:"もちろん、最終の契約書は、両方の側がそれぞれ法律の専門家に確かめてもらいます。"},
    {en:"We will send you the final version of the contract by Friday.",ja:"金曜までに、契約書の最終版をお送りします。"},
    {en:"Thank you very much. Are there any points you would like to check again?",ja:"ありがとうございました。もう一度確かめたい点はありますか？"}
   ]},
  task:"インドのホテルとの提携の主な条件（期間・料金・支払い・終了）、お互いの責任、日程、まだ決まっていない点を、1つずつ確認しながら6分でまとめて伝える。",
  taskEn:"Summarise the key terms of a partnership agreement with a hotel in India in 6 minutes: key terms, responsibilities, timeline, and one open point. Check understanding after each main point.",
  qa:[
   {q:"Can we change the payment terms to 45 days?",a:"I understand. We could accept 45 days for the set-up fee. For the monthly fee, we'd prefer to keep 30 days. Would that work for you?",ja:"支払いを45日にできますか？／わかります。導入費は45日でお受けできます。毎月の料金は30日のままにしたいのですが、いかがでしょうか？"},
   {q:"What happens to our data if the agreement ends?",a:"The data belongs to you. We will return it in a standard format and delete our copy within 30 days.",ja:"契約が終わったら、私たちのデータはどうなりますか？／データは皆さんのものです。一般的な形式でお返しし、こちらの控えは30日以内に削除します。"},
   {q:"Who pays if the training dates change?",a:"If we give each other at least two weeks' notice, there is no extra charge. Let's add that to the contract.",ja:"研修の日が変わったら、誰が費用を払いますか？／お互いに2週間以上前に知らせれば、追加の料金はかかりません。それを契約に加えましょう。"},
   {q:"Is this summary legally binding?",a:"No. This is only a summary to help us understand each other. The signed contract is what counts.",ja:"このまとめには法的な効力がありますか？／ありません。これはお互いの理解を助けるためのまとめだけです。効力があるのは、サインした契約書です。"}
  ],
  check:[
   "主な条件・責任・日程・決まっていない点の4つの順で話せたか",
   "shall を使わず、will / may でわかりやすく言いかえられたか",
   "Just to confirm... や Is that correct? で、1つずつ確認できたか",
   "決まっていない点をかくさず出し、いつまでに決めるかを言えたか",
   "最後に「専門家に契約書を確かめてもらう」と言えたか"
  ],
  slide:"表を1枚作り、左の列に Key terms / Responsibilities / Timeline、右の列に短い要点を書きます。まだ決まっていない点は、色を変えて目立たせましょう。"},
 {week:46, level:"B2-", length:"6分", title:"導入の手順と段取りを説明する",
  skill:"受け身（be + 過去分詞）と順番の言葉を使って、サービスの導入や日本酒の出荷の流れを、6分でわかりやすく説明できる。",
  lesson:[
   "今週は、ものごとの「流れ」を説明する練習です。導入の手順や出荷の段取りを話すときは、「誰がするか」より「何がされるか」が大事です。そこで受け身（be + 過去分詞）を使います。First, the bottles are packed.（まず、びんが梱包されます）のように言うと、ものの動きが主役になり、流れがすっきり伝わります。",
   "順番の言葉もセットで使います。First（まず）→ Next / Then（次に）→ After that（そのあと）→ Once 〜 is done（〜が終わったら）→ Finally（最後に）。手順は5〜7つまでにまとめ、1つの手順に1文、多くても2文にしましょう。誰がするかを言いたいときだけ、by our team（私たちのチームによって）を足します。",
   "流れの説明で聞き手がいちばん知りたいのは、「どのくらい時間がかかるか」と「自分は何をすればいいか」です。各手順に日数の目安をつけ、相手がする手順には印をつけておくと親切です。また、まだわからないこと（たとえば輸入の許可にかかる日数）は、わからないと正直に言い、確かめると約束しましょう。",
   "今週の手本は、①日本の健康とケアのサービスがインドのホテルに導入される流れと、②小谷酒店の日本酒がインドへ出荷される流れの2つを説明する話です。日数・本数・手続きの中身は練習用の例です。本当の輸出入のきまりは、必ず専門の業者や役所に確かめましょう。"
  ],
  structure:[
   {en:"Overview of the process",ja:"流れの全体像"},
   {en:"Process 1: service set-up (steps)",ja:"流れ1：サービス導入の手順"},
   {en:"Process 2: shipping sake (steps)",ja:"流れ2：日本酒の出荷の手順"},
   {en:"What we need from you",ja:"相手にお願いすること"},
   {en:"Timeline summary",ja:"日程のまとめ"}
  ],
  phrases:[
   {en:"Let me walk you through the process step by step.",ja:"流れを一つずつご説明します。",note:"流れの説明に入る決まり文句。"},
   {en:"First, the products are checked and packed.",ja:"まず、商品が確認され、梱包されます。",note:"受け身で「ものの動き」を主役に。"},
   {en:"Next, the staff are trained by our team.",ja:"次に、スタッフが私たちのチームによって研修を受けます。",note:"誰がするかは by で足す。"},
   {en:"After that, the system is set up and tested.",ja:"そのあと、しくみが準備され、試されます。",note:"2つの動きを and でつなぐ。"},
   {en:"Once the documents are approved, the goods are shipped.",ja:"書類が承認されたら、品物が出荷されます。",note:"once =「〜したら（すぐに）」。"},
   {en:"This step usually takes about two weeks.",ja:"この手順には、ふつう2週間ほどかかります。",note:"手順ごとに時間の目安を言う。"},
   {en:"This is the step where we need your help.",ja:"ここが、皆さんのご協力が必要な手順です。",note:"相手がする手順をはっきり示す。"},
   {en:"The bottles are kept cool during the whole journey.",ja:"びんは、運ぶ間ずっと冷やした状態に保たれます。",note:"品質を守る点を受け身で。"},
   {en:"I'm not sure how long this step takes in India, so I'll check and let you know.",ja:"インドでこの手順にどのくらいかかるかはわからないので、確かめてお知らせします。",note:"わからないことは正直に。"},
   {en:"Finally, the service is launched and the first guests are welcomed.",ja:"最後に、サービスが始まり、最初のお客様が迎えられます。",note:"finally で流れを締める。"}
  ],
  model:{title:"サービスの導入と日本酒の出荷の流れ（6分）", time:"6分", note:"日数・本数・手続きの中身などは練習用の例です。自分の内容に入れかえましょう。本当の輸出入の手続きは、専門の業者や役所に確かめましょう。",
   lines:[
    {en:"Good morning, everyone. Now that we have agreed on the key terms, let's talk about how things will actually happen.",ja:"皆さん、おはようございます。主な条件が決まりましたので、実際にどう進むかをお話しします。"},
    {en:"Today I'll explain two processes. The first is how our care service is set up at your hotel.",ja:"今日は2つの流れを説明します。1つめは、私たちのケアのサービスが、皆さんのホテルでどう準備されるかです。"},
    {en:"The second is how Japanese sake is shipped from my family's shop in Japan to your hotel in India.",ja:"2つめは、日本の家族の酒店から、インドの皆さんのホテルへ、日本酒がどう出荷されるかです。"},
    {en:"For each step, I'll tell you how long it takes and what we need from you.",ja:"それぞれの手順について、どのくらいかかるか、皆さんに何をお願いしたいかをお伝えします。"},
    {en:"Let me start with the care service. Let me walk you through the process step by step.",ja:"まず、ケアのサービスから。流れを一つずつご説明します。"},
    {en:"First, your current service is observed. I visit the hotel and watch how guests are welcomed and treated.",ja:"まず、今のサービスが観察されます。私がホテルにうかがい、お客様がどう迎えられ、どう施術されているかを見ます。"},
    {en:"This step usually takes two days.",ja:"この手順には、ふつう2日かかります。"},
    {en:"Next, a training plan is prepared. It is based on what I saw and on your goals.",ja:"次に、研修の計画が作られます。私が見たことと、皆さんの目標をもとにします。"},
    {en:"The plan is sent to your project manager and checked together in an online meeting.",ja:"計画は担当者の方に送られ、オンライン会議で一緒に確認されます。"},
    {en:"After that, the booking system is set up and tested.",ja:"そのあと、予約のしくみが準備され、試されます。"},
    {en:"Guest messages are translated into English and Japanese, and Hindi if you wish.",ja:"お客様へのメッセージが英語と日本語に、ご希望ならヒンディー語にも翻訳されます。"},
    {en:"This is the step where we need your help. Your guest list and your menu need to be shared with us.",ja:"ここが、皆さんのご協力が必要な手順です。お客様の名簿とメニューを共有していただく必要があります。"},
    {en:"Then the staff are trained by our team. Two full training days are held at the hotel.",ja:"それから、スタッフが私たちのチームによって研修を受けます。ホテルで丸2日の研修が行われます。"},
    {en:"Greetings, simple Japanese care and follow-up messages are practised again and again.",ja:"あいさつ、日本のかんたんなケア、フォローのメッセージが、何度もくり返し練習されます。"},
    {en:"Once the training is done, the new service is tried with a small group of guests for one week.",ja:"研修が終わったら、新しいサービスが少人数のお客様で1週間試されます。"},
    {en:"Their feedback is collected, and small changes are made.",ja:"その方々の声が集められ、小さな手直しが行われます。"},
    {en:"Finally, the service is launched and the first guests are welcomed.",ja:"最後に、サービスが始まり、最初のお客様が迎えられます。"},
    {en:"After the launch, the numbers are checked every month, and a short report is sent to your manager.",ja:"始まったあとは、毎月数字が確認され、短い報告が担当者の方に送られます。"},
    {en:"In total, the care service can be ready in about six weeks.",ja:"全部で、ケアのサービスは約6週間で準備できます。"},
    {en:"Six weeks may sound long. But each step is small, and your daily work is not stopped.",ja:"6週間は長く聞こえるかもしれません。でも一つひとつの手順は小さく、日々の仕事が止まることはありません。"},
    {en:"Moving on to the second process: shipping sake.",ja:"2つめの流れ、日本酒の出荷に移ります。"},
    {en:"My family runs Odani Sake Ten, a sake shop founded in 1957. I'm in charge of international affairs.",ja:"家族が1957年創業の酒店、小谷酒店を営んでいます。私は国際担当です。"},
    {en:"First, the sake is selected. We choose sake that matches your menu and your guests' tastes.",ja:"まず、日本酒が選ばれます。皆さんのメニューとお客様の好みに合う日本酒を選びます。"},
    {en:"Sample bottles can be sent first, so that your chef and managers can taste them.",ja:"先にサンプルのびんを送り、シェフやマネージャーの皆さんに味を見ていただくこともできます。"},
    {en:"Next, the order is confirmed. For example, the first order might be 120 bottles.",ja:"次に、注文が確定されます。たとえば、最初の注文は120本といった形です。"},
    {en:"After that, the export documents are prepared by our shipping agent in Japan.",ja:"そのあと、輸出の書類が、日本の輸送業者によって準備されます。"},
    {en:"At the same time, the import licence and labels must be checked on the Indian side.",ja:"同時に、インド側で、輸入の許可とラベルが確認される必要があります。"},
    {en:"This is another step where we need your help, because the importer in India handles it.",ja:"これも皆さんのご協力が必要な手順です。インドの輸入業者が扱うからです。"},
    {en:"Honestly, I'm not sure how long this step takes in India, so I'll check and let you know.",ja:"正直に申し上げると、インドでこの手順にどのくらいかかるかはわからないので、確かめてお知らせします。"},
    {en:"Once the documents are approved, the bottles are packed carefully and shipped by sea.",ja:"書類が承認されたら、びんがていねいに梱包され、船で出荷されます。"},
    {en:"Sake is sensitive to heat and light, so the bottles are kept cool during the whole journey.",ja:"日本酒は熱と光に弱いので、運ぶ間ずっと冷やした状態に保たれます。"},
    {en:"The shipment usually takes several weeks, depending on the port and the season.",ja:"船での輸送には、港や季節によって、ふつう数週間かかります。"},
    {en:"Then the goods are cleared through customs and delivered to your hotel.",ja:"それから、品物が税関を通され、ホテルに届けられます。"},
    {en:"Finally, the sake is stored in a cool place, and your staff are shown how to serve it.",ja:"最後に、日本酒は涼しい場所に保管され、スタッフの皆さんに出し方が伝えられます。"},
    {en:"For example, which sake is served cold, which one is served warm, and which glass is used.",ja:"たとえば、どの日本酒を冷やして出すか、どれを温めるか、どのグラスを使うかです。"},
    {en:"A short card is also prepared for each sake. The region, the taste and the best food are written on it.",ja:"日本酒ごとに短いカードも用意されます。産地、味、合う料理が書かれています。"},
    {en:"Guests love these small stories. They turn a drink into a memory.",ja:"お客様は、こうした小さな物語が大好きです。一杯のお酒が思い出に変わります。"},
    {en:"That brings me to what we need from you. Let me sum up your part in both processes.",ja:"そこで、皆さんにお願いしたいことの話になります。2つの流れでの皆さんの役目をまとめます。"},
    {en:"For the care service, your guest list, your menu and two days for staff training are needed.",ja:"ケアのサービスには、お客様の名簿、メニュー、そしてスタッフ研修のための2日間が必要です。"},
    {en:"For the sake, an importer in India and a cool storage space are needed.",ja:"日本酒には、インドの輸入業者と、涼しい保管場所が必要です。"},
    {en:"To conclude, the care service can be ready in about six weeks.",ja:"まとめると、ケアのサービスは約6週間で準備できます。"},
    {en:"The sake can arrive a little later, because the import steps take more time.",ja:"日本酒は、輸入の手順に時間がかかるので、少しあとに届きます。"},
    {en:"So I suggest we start the sake process now, at the same time as the training plan.",ja:"そこで、日本酒の手続きを今すぐ、研修の計画と同時に始めることをご提案します。"},
    {en:"That way, both can be ready for the first Japanese evening.",ja:"そうすれば、最初の日本の夜までに両方の準備ができます。"},
    {en:"Thank you very much. Do you have any questions about the steps?",ja:"ありがとうございました。手順について、ご質問はありますか？"}
   ]},
  task:"日本のケアのサービスがインドのホテルに導入される流れと、日本酒がインドに出荷される流れを、受け身と順番の言葉を使って、手順ごとに時間の目安をつけて6分で説明する。",
  taskEn:"Explain two processes in 6 minutes: how a Japanese care service is set up at a hotel in India, and how sake is shipped from Japan to India. Use the passive voice and sequence words, and give a time for each step.",
  qa:[
   {q:"Can the sake be sent by air to save time?",a:"It can, but air shipping costs much more. For the first order, I'd suggest sea shipping, and air only for samples.",ja:"時間を節約するため、日本酒を飛行機で送れますか？／できますが、航空便はずっと高くなります。最初の注文は船便、サンプルだけ航空便をおすすめします。"},
   {q:"Who is responsible if bottles are broken during shipping?",a:"Good question. The goods will be insured during shipping. The details will be written in the order contract.",ja:"運ぶ途中でびんが割れたら、誰の責任ですか？／よい質問です。品物には輸送中の保険がかけられます。くわしくは注文の契約に書かれます。"},
   {q:"Can the training be done online instead?",a:"Some parts can be done online, like the follow-up messages. But the care itself needs to be practised in person.",ja:"研修をオンラインでできますか？／フォローのメッセージなど、一部はオンラインでできます。でもケアそのものは、対面で練習する必要があります。"},
   {q:"What if our importer needs extra documents?",a:"Please send me the list, and I'll ask our shipping agent to prepare them. We'll keep you updated every week.",ja:"輸入業者が追加の書類を必要としたら？／一覧をお送りください。輸送業者に準備を頼みます。毎週、進み具合をお知らせします。"}
  ],
  check:[
   "受け身（is checked / are trained / is shipped など）を10回以上使えたか",
   "First / Next / After that / Once / Finally の順番の言葉を使えたか",
   "それぞれの手順に、時間の目安をつけられたか",
   "相手にお願いする手順をはっきり示せたか",
   "わからないこと（インドでの日数など）を正直に言い、確かめると約束できたか"
  ],
  slide:"手順は左から右への矢印で5〜7つの箱に並べ、箱の下に日数、相手がする手順には色をつけましょう。2つの流れは別のスライドに分けます。"},
 {week:47, level:"B2-", length:"6分", title:"インドの聞き手に合わせる",
  skill:"インドの聞き手への敬意と気づかいを示しながら話し、インド英語の言い回しを聞き取って、6分のプレゼンを対話のように進められる。",
  lesson:[
   "今週は、インドの聞き手に合わせてプレゼンを整える練習です。始め方は、手を胸の前で合わせて Namaste.（ナマステ）と言うと、それだけで場がやわらぎます。そのあと英語で、来てくれたことへのお礼と、インドの文化への敬意をひとこと添えましょう。インドには「お客様は神様」という意味の Atithi Devo Bhava という考えがあり、日本のおもてなしとよく似ています。共通点から話し始めると、聞き手は「自分たちの話だ」と感じてくれます。",
   "インドのビジネスでは、関係づくりがとても大切です。いきなり本題に入るより、相手の会社や街への関心を少し話してから始めます。また、質問や意見が途中で出ることも多いので、話を止められても慌てずに、Good point. Let me answer that now. と受け止めましょう。日程を決めるときは、ディワリなどの大きなお祭りの時期を避ける気づかいも喜ばれます。イベントの料理では、ベジタリアンの方への配慮を必ず入れます。",
   "インド英語には、日本の教科書にない言い方があります。do the needful（必要な対応をしてください）、revert（返事をする）、prepone（予定を早める）、kindly（どうぞ〜してください）、out of station（出張中）、lakh（10万）と crore（1,000万）などです。話す速さが速く、r の音がはっきりしているのも特徴です。聞き取れないときは、Sorry, could you say that a little more slowly? と何度でも聞き返してかまいません。",
   "首を横に小さくかしげる動き（ヘッドボブル）は、「はい・わかりました」の意味のことが多いです。日本人の「いいえ」と取りちがえないようにしましょう。今週の手本は、インドのホテルの方に、インドのもてなしと日本のおもてなしの共通点から話を始め、一緒に作るサービスを提案する話です。"
  ],
  structure:[
   {en:"Namaste and respect",ja:"ナマステと敬意"},
   {en:"Common ground",ja:"共通点（インドのもてなしと日本のおもてなし）"},
   {en:"Our proposal, adapted",ja:"相手に合わせた提案"},
   {en:"Cultural care points",ja:"文化への気づかい"},
   {en:"Dialogue and next step",ja:"対話と次の一歩"}
  ],
  phrases:[
   {en:"Namaste. It's an honour to be here with you today.",ja:"ナマステ。今日、皆さんとご一緒できて光栄です。",note:"手を合わせて、ゆっくり。最初の印象が決まる。"},
   {en:"I have great respect for Indian hospitality.",ja:"インドのもてなしを、とても尊敬しています。",note:"敬意をはっきり言葉にする。"},
   {en:"In India, you say Atithi Devo Bhava. In Japan, we have a similar idea called omotenashi.",ja:"インドには Atithi Devo Bhava という言葉があります。日本にも、おもてなしという似た考えがあります。",note:"共通点から入ると距離が縮まる。"},
   {en:"Please correct me if I'm wrong. You know this market much better than I do.",ja:"まちがっていたら直してください。この市場のことは、私よりずっとよくご存じですから。",note:"謙虚さを示し、対話を引き出す。"},
   {en:"Good point. Let me answer that now.",ja:"よいご指摘です。今お答えします。",note:"途中の質問も、慌てず受け止める。"},
   {en:"Sorry, could you say that a little more slowly?",ja:"すみません、もう少しゆっくり言っていただけますか？",note:"聞き取れないときは何度聞き返してもよい。"},
   {en:"Just to make sure I understood, you'd like us to revert by Monday?",ja:"確認ですが、月曜までにお返事すればよいということですね？",note:"revert = インド英語で「返事をする」。"},
   {en:"We'll make sure there are vegetarian options at every event.",ja:"どのイベントでも、ベジタリアンの料理を必ずご用意します。",note:"食事への配慮は、言葉にして約束する。"},
   {en:"We'll avoid the festival season when we plan the training.",ja:"研修を計画するときは、お祭りの時期を避けます。",note:"相手の暦への気づかい。"},
   {en:"I'd love to hear your ideas. How would your guests feel about this?",ja:"ぜひ皆さんのお考えを聞かせてください。お客様はこれをどう感じると思いますか？",note:"話の途中で聞き手に問いかける。"}
  ],
  model:{title:"インドのもてなしと日本のおもてなしを結ぶ（6分）", time:"6分", note:"相手のホテルの様子や日程は練習用の例です。自分の場面に入れかえましょう。",
   lines:[
    {en:"Namaste. It's an honour to be here with you today.",ja:"ナマステ。今日、皆さんとご一緒できて光栄です。"},
    {en:"Thank you for welcoming me so warmly. I always feel at home when I visit India.",ja:"温かく迎えていただき、ありがとうございます。インドに来るといつも、くつろいだ気持ちになります。"},
    {en:"Before I begin, I'd like to say one thing. I have great respect for Indian hospitality.",ja:"始める前に、ひとこと申し上げたいことがあります。私はインドのもてなしを、とても尊敬しています。"},
    {en:"In India, you say Atithi Devo Bhava. The guest is like a god.",ja:"インドには Atithi Devo Bhava という言葉があります。お客様は神様のような存在だ、という意味です。"},
    {en:"In Japan, we have a similar idea called omotenashi. It means caring for the guest with your whole heart.",ja:"日本にも、おもてなしという似た考えがあります。心をこめてお客様を気づかうことです。"},
    {en:"So today, I'm not here to teach you hospitality. You already know it very well.",ja:"ですから今日は、皆さんにもてなしを教えに来たのではありません。皆さんはもう、よくご存じです。"},
    {en:"I'm here to share some Japanese ways that could add something new for your guests.",ja:"お客様に何か新しいものを加えられる、日本のやり方をいくつかご紹介しに来ました。"},
    {en:"My talk has three parts. First, what our two cultures have in common.",ja:"話は3つです。1つめは、私たちの2つの文化の共通点です。"},
    {en:"Second, a few Japanese ideas for your hotel. And third, some points I'd like to plan carefully with you.",ja:"2つめは、皆さんのホテルのための日本の工夫をいくつか。3つめは、皆さんと一緒にていねいに計画したい点です。"},
    {en:"Please feel free to stop me at any time. I'd love this to be a conversation.",ja:"いつでも遠慮なく止めてください。この時間を、対話にしたいと思っています。"},
    {en:"Let me start with what we have in common.",ja:"まず、共通点からお話しします。"},
    {en:"In both countries, a guest is welcomed with warmth, and family is very important.",ja:"どちらの国でも、お客様は温かく迎えられ、家族がとても大切にされます。"},
    {en:"In both countries, food and drink are a way to show respect.",ja:"どちらの国でも、食べ物や飲み物は敬意を表す方法です。"},
    {en:"In India, a guest is offered chai. In Japan, a guest is offered green tea. The cup is different, but the heart is the same.",ja:"インドではお客様にチャイを、日本では緑茶を出します。器はちがっても、心は同じです。"},
    {en:"And in both countries, small gestures matter, like a greeting with the hands together, or a bow.",ja:"そしてどちらの国でも、手を合わせたあいさつやおじぎのような、小さなしぐさが大切です。"},
    {en:"Moving on to the Japanese ideas. The first idea is quiet attention.",ja:"日本の工夫に移ります。1つめは、さりげない気配りです。"},
    {en:"In Japan, staff try to notice what a guest needs before the guest asks.",ja:"日本では、スタッフはお客様が頼む前に、必要なものに気づこうとします。"},
    {en:"For example, a guest who looks tired after a long flight is offered a warm towel and a quiet room.",ja:"たとえば、長いフライトで疲れた様子のお客様には、温かいおしぼりと静かな部屋がご用意されます。"},
    {en:"The second idea is Japanese care for the body. I'm an acupuncturist and judo therapist, so this is my field.",ja:"2つめは、日本の体のケアです。私は鍼灸師・柔道整復師なので、これは私の専門です。"},
    {en:"Your therapists could learn simple care for posture, tired legs and stiff shoulders.",ja:"セラピストの皆さんが、姿勢、疲れた脚、こった肩のためのかんたんなケアを学べます。"},
    {en:"The third idea is remembering each guest. A simple booking system can help with this.",ja:"3つめは、一人ひとりのお客様を覚えることです。かんたんな予約のしくみが、その助けになります。"},
    {en:"I built this kind of system for my own clinic in Japan. It shows each patient's history and preferences on one screen.",ja:"私は日本の自分の院のために、こうしたしくみを作りました。一人ひとりの患者さんの記録と好みを、1つの画面に出します。"},
    {en:"Imagine a guest who returns after one year. Your staff remember the guest's name, favourite tea and pillow.",ja:"1年ぶりにもどってきたお客様を想像してください。スタッフがお客様の名前、好きなお茶、まくらを覚えています。"},
    {en:"That guest will feel truly welcomed, in the spirit of both Atithi Devo Bhava and omotenashi.",ja:"そのお客様は、Atithi Devo Bhava とおもてなしの両方の心で、本当に迎えられたと感じるでしょう。"},
    {en:"Please correct me if I'm wrong. You know this market much better than I do.",ja:"まちがっていたら直してください。この市場のことは、私よりずっとよくご存じですから。"},
    {en:"I'd love to hear your ideas. How would your guests feel about this kind of care?",ja:"ぜひ皆さんのお考えを聞かせてください。お客様は、こうしたケアをどう感じると思いますか？"},
    {en:"Good point. Many of your guests are business travellers, so short sessions of twenty minutes could work well.",ja:"よいご指摘です。お客様の多くは出張の方なので、20分の短いケアがよさそうですね。"},
    {en:"That's very helpful. Thank you. This is exactly why I wanted to hear from you.",ja:"とても参考になります。ありがとうございます。だからこそ、皆さんのお話を聞きたかったのです。"},
    {en:"So we could design a short menu for business travellers, and a longer one for families on holiday.",ja:"そうすると、出張のお客様向けの短いメニューと、休暇中のご家族向けの長いメニューを作れますね。"},
    {en:"That brings me to the points I'd like to plan carefully with you.",ja:"そこで、皆さんと一緒にていねいに計画したい点の話になります。"},
    {en:"First, food. We'll make sure there are vegetarian options at every event, including the Japanese evening.",ja:"1つめは食事です。日本の夜も含めて、どのイベントでもベジタリアンの料理を必ずご用意します。"},
    {en:"Japanese cuisine has many vegetarian dishes, like tofu, vegetables and rice, so this is easy to do.",ja:"日本料理には、豆腐、野菜、ごはんなど、ベジタリアンの料理がたくさんあるので、これはかんたんにできます。"},
    {en:"Some guests don't drink alcohol, so we'll also prepare Japanese teas for them.",ja:"お酒を飲まないお客様もいらっしゃるので、日本茶もご用意します。"},
    {en:"Second, timing. We'll avoid the festival season, such as Diwali, when we plan the training.",ja:"2つめは時期です。研修を計画するときは、ディワリなどのお祭りの時期を避けます。"},
    {en:"Your staff will be very busy then, and they should enjoy the festival with their families.",ja:"その時期はスタッフの皆さんがとても忙しいですし、家族とお祭りを楽しむべきですから。"},
    {en:"Third, language. I'll use simple English in the training, and we can add Hindi materials if that helps.",ja:"3つめは言葉です。研修ではやさしい英語を使い、役に立つならヒンディー語の資料も加えられます。"},
    {en:"And if I don't understand something, I'll ask. Sorry, could you say that a little more slowly?",ja:"そして、わからないことがあれば聞き返します。すみません、もう少しゆっくり言っていただけますか、と。"},
    {en:"I hope you don't mind. I'd rather ask twice than make a mistake with your guests.",ja:"どうかお許しください。お客様に対してまちがえるより、2回聞くほうがよいと思っています。"},
    {en:"To conclude, our two cultures share the same heart for guests.",ja:"まとめると、私たちの2つの文化は、お客様への同じ心を持っています。"},
    {en:"Japanese ideas like quiet attention, body care and remembering each guest can add something new.",ja:"さりげない気配り、体のケア、一人ひとりを覚えることといった日本の工夫は、新しい何かを加えられます。"},
    {en:"And we will plan the details with respect for your food, your calendar and your language.",ja:"そして、皆さんの食事、暦、言葉を大切にしながら、細かい点を計画します。"},
    {en:"As a next step, could you share the dates that are best for your team?",ja:"次の一歩として、チームにとっていちばんよい日程を教えていただけますか？"},
    {en:"Then I'll prepare a plan and revert to you by next Monday.",ja:"そうすれば計画を用意して、来週の月曜までにお返事します。"},
    {en:"Just to make sure I understood, Monday is fine for you?",ja:"確認ですが、月曜でよろしいでしょうか？"},
    {en:"Wonderful. Thank you very much for listening, and for your ideas today. Dhanyavaad.",ja:"よかったです。お聞きいただき、そして今日アイデアをいただき、ありがとうございました。ダンニャワード（ありがとう）。"}
   ]},
  task:"インドのホテルの方に、Namaste で始め、インドのもてなしと日本のおもてなしの共通点から話を入り、食事・時期・言葉への気づかいを入れた提案を、途中で問いかけながら6分で話す。",
  taskEn:"Give a 6-minute talk to hotel managers in India. Start with Namaste, find common ground between Indian hospitality and omotenashi, include care points about food, timing and language, and ask the audience questions during the talk.",
  qa:[
   {q:"Kindly revert with the training dates by Friday. Can you do the needful?",a:"Of course. I'll send you the training dates by Friday. Just to confirm, should I send them to you or to your manager?",ja:"金曜までに研修の日程をお返事ください。対応していただけますか？／もちろんです。金曜までに研修の日程をお送りします。確認ですが、あなたとマネージャーの方、どちらにお送りすればよいですか？"},
   {q:"Can we prepone the training to next month?",a:"You'd like to move it earlier, to next month? I think that's possible. Let me check my schedule and confirm tomorrow.",ja:"研修を来月に早められますか？／来月に早めたい、ということですね？ できると思います。予定を確認して、明日お知らせします。"},
   {q:"Our budget is about five lakh rupees. Is that enough?",a:"Five lakh, so 500,000 rupees. Thank you. That should be enough for a pilot at one hotel. I'll prepare a plan within that budget.",ja:"予算は5ラークルピーくらいです。足りますか？／5ラーク、つまり50万ルピーですね。ありがとうございます。1つのホテルでの試行には十分だと思います。その予算内で計画を作ります。"},
   {q:"Will the Japanese care work for Indian body types and lifestyles?",a:"That's an important question. The basic ideas of posture and recovery are the same for everyone. But I'd like to learn from your therapists and adjust the care together.",ja:"日本のケアは、インドの人の体や暮らしに合いますか？／大切なご質問です。姿勢と回復の基本の考えは、誰にでも同じです。でも、セラピストの皆さんから学び、一緒にケアを調整したいと思います。"}
  ],
  check:[
   "Namaste で始め、インドの文化への敬意をひとこと言えたか",
   "共通点から話し始め、「教えに来た」という言い方を避けられたか",
   "食事（ベジタリアン・お酒を飲まない方）と時期（お祭り）への気づかいを入れたか",
   "話の途中で聞き手に1回以上問いかけたか",
   "revert / prepone / do the needful / lakh などを聞いて、正しく言い直して確認できたか"
  ],
  slide:"最初のスライドに、インドと日本の2つの言葉（Atithi Devo Bhava ／ Omotenashi）を左右に並べ、まん中に「同じ心」を表す絵を1つ置きましょう。"},
 {week:48, level:"B2-", length:"7分", title:"質疑応答",
  skill:"「受け止める→確認する→答える→確かめる」の4つの手順で、難しい質問・わからない質問・反対意見にも落ち着いて答えられる。",
  lesson:[
   "今週は、プレゼンのあとの質疑応答です。多くの人が「質問がこわい」と感じますが、質問はあなたの話に興味を持ってくれた証拠です。答え方には型があります。①受け止める（Thank you for your question.）②確認する（So your question is... / If I understand correctly...）③答える（結論を先に、理由を1つか2つ）④確かめる（Does that answer your question?）。この4つの手順を守れば、英語が完璧でなくても、落ち着いて見えます。",
   "②の「確認する」は、とても大切です。質問を自分の言葉で言い直すと、まちがった答えを防げるうえに、考える時間が数秒できます。聞き取れなかったときは、Sorry, could you repeat the question? と言いましょう。これは失礼ではなく、ていねいなことです。",
   "困ったときの言い方も用意しておきます。答えがわからないときは、うそをつかずに That's a good question. I don't have the exact answer right now, but I'll check and get back to you by Friday. と言い、本当に期限までに返事をします。反対意見には、まず I understand your concern. と相手の気持ちを受け止め、そのあとで That's a fair point. However, ... と自分の考えを伝えます。言い争わず、「一緒に考える」姿勢を見せましょう。",
   "時間が足りないときは、I'm afraid we're running out of time. Could we talk about this after the session? と言って、あとで話す約束をします。今週の手本は、提携の提案のあとの質疑応答で、5つの質問（かんたんな質問・数字の質問・わからない質問・反対意見・厳しい質問）に答える話です。数字は練習用の例です。"
  ],
  structure:[
   {en:"Acknowledge",ja:"受け止める"},
   {en:"Clarify",ja:"確認する（言い直す）"},
   {en:"Answer (conclusion first)",ja:"答える（結論が先）"},
   {en:"Check",ja:"確かめる"},
   {en:"Close the Q&A",ja:"質疑応答を締める"}
  ],
  phrases:[
   {en:"Thank you for your question.",ja:"ご質問ありがとうございます。",note:"①受け止める。どんな質問にもまずこれ。"},
   {en:"If I understand correctly, you're asking about the cost after the pilot.",ja:"私の理解が正しければ、試行のあとの費用についてのご質問ですね。",note:"②確認する。考える時間もできる。"},
   {en:"Sorry, could you repeat the question?",ja:"すみません、もう一度ご質問を言っていただけますか？",note:"聞き取れないときは、遠慮なく。"},
   {en:"The short answer is yes.",ja:"かんたんに言うと、答えは「はい」です。",note:"③答える。結論を先に。"},
   {en:"Does that answer your question?",ja:"これでお答えになっていますか？",note:"④確かめる。足りなければ補える。"},
   {en:"That's a good question. I don't have the exact answer right now.",ja:"よいご質問です。今は正確な答えを持っていません。",note:"わからないときは、正直に。"},
   {en:"I'll check and get back to you by Friday.",ja:"確認して、金曜までにご連絡します。",note:"わからないときは、期限を約束する。"},
   {en:"I understand your concern.",ja:"ご心配はよくわかります。",note:"反対意見には、まず気持ちを受け止める。"},
   {en:"That's a fair point. However, let me share another way to look at it.",ja:"もっともなご指摘です。ただ、別の見方もお伝えさせてください。",note:"相手を認めてから、自分の考えを。"},
   {en:"I'm afraid we're running out of time. Could we talk about this after the session?",ja:"申し訳ありませんが、時間が迫っています。このあと、お話しできますか？",note:"時間がないときの、ていねいな区切り方。"}
  ],
  model:{title:"提携提案のあとの質疑応答（7分）", time:"7分", note:"質問の中身・金額・数字は練習用の例です。自分の場面に入れかえましょう。",
   lines:[
    {en:"Thank you very much for listening. Let me quickly sum up before we move to questions.",ja:"お聞きいただき、ありがとうございました。質問に移る前に、手短にまとめます。"},
    {en:"I proposed a three-month pilot at one of your hotels, with Japanese care, hospitality training and a booking system.",ja:"ホテルの1つで、日本のケア、おもてなし研修、予約のしくみを組み合わせた3か月の試行をご提案しました。"},
    {en:"Now I'd be happy to take your questions. Yes, please, the lady in the front.",ja:"それでは、ご質問をお受けします。はい、どうぞ、前の方。"},
    {en:"Thank you for your question. So your question is whether the training can be done in Hindi.",ja:"ご質問ありがとうございます。つまり、研修をヒンディー語でできるかというご質問ですね。"},
    {en:"The short answer is: partly, yes. I'll lead the training in simple English.",ja:"かんたんに言うと、一部はできます。研修は私がやさしい英語で行います。"},
    {en:"But all the handouts can be translated into Hindi, and one of your managers could help as an interpreter.",ja:"ただ、配る資料はすべてヒンディー語に訳せますし、マネージャーの方に通訳としてお手伝いいただくこともできます。"},
    {en:"Does that answer your question? Good. Thank you.",ja:"これでお答えになっていますか？ よかったです。ありがとうございます。"},
    {en:"Next question, please. Yes, the gentleman on the right.",ja:"次のご質問をどうぞ。はい、右側の方。"},
    {en:"Thank you. If I understand correctly, you're asking about the cost after the pilot. Is that right?",ja:"ありがとうございます。私の理解が正しければ、試行のあとの費用についてのご質問ですね。合っていますか？"},
    {en:"Yes. After the pilot, the monthly fee would be 30,000 rupees per hotel.",ja:"はい。試行のあとは、毎月の料金がホテル1つにつき3万ルピーになります。"},
    {en:"If you add more than three hotels, we would offer a lower rate for each hotel.",ja:"ホテルを3つより多く加えていただければ、1つあたりの料金を下げます。"},
    {en:"I'll put these numbers in the written proposal, so you can compare them easily.",ja:"これらの数字は書面の提案書に入れますので、かんたんに見くらべていただけます。"},
    {en:"Does that answer your question? Thank you.",ja:"これでお答えになっていますか？ ありがとうございます。"},
    {en:"Yes, please, at the back. Sorry, could you repeat the question? I couldn't hear the last part.",ja:"はい、うしろの方どうぞ。すみません、もう一度ご質問を言っていただけますか？ 最後のところが聞こえませんでした。"},
    {en:"Thank you. So you'd like to know how many hotels in India already use this system.",ja:"ありがとうございます。つまり、インドでこのしくみをすでに使っているホテルがいくつあるか、ですね。"},
    {en:"That's a good question. I'd like to be honest with you.",ja:"よいご質問です。正直にお答えしたいと思います。"},
    {en:"The system was first built for my own clinic in Japan, and now our partner clinics use it.",ja:"このしくみは最初、日本の私の院のために作られ、今は提携院が使っています。"},
    {en:"Your hotel would be one of the first hotels in India to use it. That's exactly why we suggest a pilot.",ja:"皆さんのホテルは、インドで最初にこれを使うホテルの1つになります。だからこそ試行をご提案しているのです。"},
    {en:"As for other projects in India, I don't have the exact details right now.",ja:"インドでのほかの事例については、今は正確な情報を持っていません。"},
    {en:"I'll check and get back to you by Friday. Is that all right?",ja:"確認して、金曜までにご連絡します。それでよろしいでしょうか？"},
    {en:"Thank you. Yes, the lady in the middle.",ja:"ありがとうございます。はい、まん中の方。"},
    {en:"Thank you for your question. If I understand correctly, you're worried about guest data. Who can see it, and where is it kept?",ja:"ご質問ありがとうございます。私の理解が正しければ、お客様のデータについてのご心配ですね。誰が見られて、どこに保管されるのか。"},
    {en:"The short answer is that the data belongs to your hotel, and only your staff and our support team can see it.",ja:"かんたんに言うと、データは皆さんのホテルのもので、見られるのは皆さんのスタッフと私たちのサポートの担当だけです。"},
    {en:"We use it only to prepare your reports. We never share it with anyone else.",ja:"報告書を作るためだけに使います。ほかの誰とも共有しません。"},
    {en:"As for the exact rules on data in India, your legal team should check them. We will follow their advice.",ja:"インドでのデータの正確なきまりについては、皆さんの法務の担当に確かめていただくのがよいです。そのご助言に従います。"},
    {en:"Does that answer your question? Thank you.",ja:"これでお答えになっていますか？ ありがとうございます。"},
    {en:"Next question, please. Yes, sir.",ja:"次のご質問をどうぞ。はい、どうぞ。"},
    {en:"I see. So your view is that Japanese care is too slow for busy Indian guests.",ja:"なるほど。つまり、日本のケアは忙しいインドのお客様にはゆっくりすぎる、というお考えですね。"},
    {en:"I understand your concern. Many of your guests are busy business travellers.",ja:"ご心配はよくわかります。お客様の多くは、忙しい出張の方ですから。"},
    {en:"That's a fair point. However, let me share another way to look at it.",ja:"もっともなご指摘です。ただ、別の見方もお伝えさせてください。"},
    {en:"Japanese care doesn't have to be long. The idea is to notice what the guest needs, quickly and quietly.",ja:"日本のケアは長くなくてよいのです。お客様が必要なことに、すばやく、さりげなく気づくという考えです。"},
    {en:"For busy guests, we could design a twenty-minute session. It could even be done before breakfast.",ja:"忙しいお客様には、20分のケアを作れます。朝食の前にすることもできます。"},
    {en:"In fact, busy people often need care the most, because they have no time to rest.",ja:"実際、忙しい人ほど、休む時間がないので、ケアがいちばん必要なことが多いのです。"},
    {en:"I'd suggest we test the short session during the pilot and see how guests react. Would that be acceptable?",ja:"試行の間に短いケアを試し、お客様の反応を見ることをご提案します。それでいかがでしょうか？"},
    {en:"Thank you. I appreciate your honest opinion.",ja:"ありがとうございます。率直なご意見に感謝します。"},
    {en:"We have time for one more question. Yes, madam.",ja:"あと1つご質問をお受けできます。はい、どうぞ。"},
    {en:"So your question is: what happens if the pilot fails? That's an important question.",ja:"つまり、試行がうまくいかなかったらどうなるか、というご質問ですね。大切なご質問です。"},
    {en:"First, we agree on clear goals before we start, such as guest reviews and repeat bookings.",ja:"まず、始める前に、お客様の評価やリピートの予約など、はっきりした目標を一緒に決めます。"},
    {en:"If the goals are not met after three months, you can simply stop. There is no long contract.",ja:"3か月後に目標に届かなければ、そこでやめていただけます。長い契約はありません。"},
    {en:"Your staff will keep the training and the materials, so the time is not wasted.",ja:"スタッフの皆さんには研修と資料が残るので、時間はむだになりません。"},
    {en:"And I will also learn from it. I'd rather know the truth than hide a problem.",ja:"そして、私もそこから学びます。問題をかくすより、本当のことを知りたいのです。"},
    {en:"Does that answer your question? Thank you.",ja:"これでお答えになっていますか？ ありがとうございます。"},
    {en:"I'm afraid we're running out of time. I see a few more hands.",ja:"申し訳ありませんが、時間が迫っています。まだ手が挙がっていますね。"},
    {en:"Could we talk about your questions after the session? I'll stay here for another thirty minutes.",ja:"このあと、ご質問についてお話しできますか？ もう30分ここにおります。"},
    {en:"Let me sum up the answers. The training handouts can be in Hindi, and larger groups get a lower rate.",ja:"お答えをまとめます。研修の資料はヒンディー語にでき、多くのホテルで始めれば料金は下がります。"},
    {en:"Guest data belongs to your hotel, and it is used only for your reports.",ja:"お客様のデータは皆さんのホテルのもので、報告書のためだけに使われます。"},
    {en:"Short sessions for busy guests will be tested in the pilot, and you can stop at any time if the goals are not met.",ja:"忙しいお客様向けの短いケアは試行で試し、目標に届かなければいつでもやめられます。"},
    {en:"And I'll send you information about other projects in India by Friday.",ja:"そして、インドでのほかの事例については、金曜までにお送りします。"},
    {en:"Thank you all for your excellent questions. They will help us make this plan even better.",ja:"すばらしいご質問を、皆さんありがとうございました。この計画をさらによくするのに役立ちます。"}
   ]},
  task:"提携の提案のあとの質疑応答を7分で行う。AIに5つの質問（かんたん・数字・わからない・反対意見・厳しい質問）をしてもらい、4つの手順（受け止める→確認する→答える→確かめる）で答える。",
  taskEn:"Run a 7-minute Q&A session after a partnership proposal. Ask me five questions, including a difficult one, an objection and one I can't answer. I will use four steps: acknowledge, clarify, answer, check.",
  qa:[
   {q:"Honestly, why should we trust a small clinic owner from a small Japanese city?",a:"That's a fair question. I can't show you the size of a big company. But I can show you real results from my clinic, and I'll be personally responsible for this project. That's why we suggest a small pilot first.",ja:"率直に言って、なぜ日本の小さな街の小さな院の院長を信用すべきなのですか？／もっともなご質問です。大きな会社の規模はお見せできません。でも、私の院での本当の成果をお見せでき、このプロジェクトには私自身が責任を持ちます。だからこそ、まず小さな試行をご提案しているのです。"},
   {q:"Your price is higher than local consultants. Why?",a:"I understand your concern. Our price includes the system, monthly reports and training by a licensed therapist. If you compare the full package, I believe it's good value. But let's look at the numbers together.",ja:"あなたの価格は、地元のコンサルタントより高いです。なぜですか？／ご心配はわかります。私たちの価格には、しくみ、毎月の報告、資格を持つ施術者による研修が含まれます。全体でくらべれば、払う価値があると考えます。でも、一緒に数字を見てみましょう。"},
   {q:"What is the exact return rate we can expect in the first month?",a:"That's a good question. I can't promise an exact number, because every hotel is different. I'll check your current data and send you a realistic estimate by Friday.",ja:"最初の1か月で、正確にどのくらいのリピート率が見込めますか？／よいご質問です。ホテルごとにちがうので、正確な数字はお約束できません。今のデータを確認して、金曜までに現実的な見込みをお送りします。"},
   {q:"Isn't omotenashi just good manners? We already have that.",a:"You're right that your team already has wonderful manners. Omotenashi adds one more thing: noticing needs before the guest asks. I think it can build on what you already do well.",ja:"おもてなしは、ただのよいマナーではないですか？ それならもうあります。／チームの皆さんがすでにすばらしいマナーをお持ちなのは、そのとおりです。おもてなしは、お客様が頼む前に必要に気づく、という1つを加えます。皆さんがすでにうまくできていることの上に積み重ねられると思います。"},
   {q:"If we sign, can you guarantee that you will visit India every month?",a:"Let me be honest. I visit India regularly, but I can't promise every month. During the pilot, I'll be there for the training and the review, and I'll support your team online every week.",ja:"契約したら、毎月インドに来ると保証できますか？／正直に申し上げます。インドには定期的に来ていますが、毎月とはお約束できません。試行の間は、研修と見直しのときにうかがい、毎週オンラインでチームを支えます。"}
  ],
  check:[
   "どの質問にも、受け止める→確認する→答える→確かめる の4つの手順で答えられたか",
   "答えの最初に結論を言えたか（The short answer is...）",
   "わからない質問に、うそをつかず、期限つきで返事を約束できたか",
   "反対意見に、まず I understand your concern. と受け止めてから答えられたか",
   "時間がないとき、ていねいに区切ってあとで話す約束ができたか"
  ],
  slide:"質疑応答の間は、最後のスライドに「3つの要点」と連絡先を出したままにしましょう。答えに使えそうなグラフは、予備のスライドとして最後のうしろに用意しておくと安心です。"},
 {week:49, level:"B2-", length:"3分ピッチ＋会話（約7分）", title:"展示会・短い登壇での3分ピッチ",
  skill:"展示会の短い登壇で、つかみ→困りごと→解決→証拠→呼びかけ の3分ピッチを話し、そのあとブースでの会話で人とのつながりを作れる。",
  lesson:[
   "今週は、展示会やイベントでの「3分ピッチ」と、そのあとの人との会話（ネットワーキング）の練習です。3分は約350〜400語。長いプレゼンを縮めるのではなく、最初から3分用に組み立てます。型は、①つかみ（問いかけや短い場面）②聞き手の困りごと ③自分の解決 ④証拠（本当の経験）⑤呼びかけ（ブースに来てください、など）です。",
   "つかみは、最初の15秒で決まります。Have you ever...?（〜したことはありますか？）や Imagine...（想像してください）で、聞き手を場面の中に連れていきましょう。スライドは3〜4枚、1枚に1つのことだけ。最後の呼びかけは、場所と時間をはっきり言います（Please visit us at Booth 24 this afternoon.）。",
   "ピッチのあとの会話は、「話しかける→広げる→つなげる→締める」の流れです。話しかけるときは Hi, I'm Akihiro. Did you enjoy the session? のように軽く。広げるときは What brings you to this expo?（今日はどうしてこちらに？）のような開いた質問をします。つなげるときは、相手の仕事と自分の仕事の接点を見つけ、締めるときは名刺を交換して、次に連絡する約束をします。",
   "相手の話を聞く時間を、自分が話す時間より長くするのがコツです。30秒で自分を紹介できる短い版（エレベーターピッチ）も覚えておきましょう。今週の手本は、インドのウェルネスとホスピタリティの展示会での3分ピッチ、30秒の短い版、ブースでの会話の3つです。展示会の名前やブースの番号は練習用の例です。"
  ],
  structure:[
   {en:"Hook (15 seconds)",ja:"つかみ（15秒）"},
   {en:"Problem",ja:"聞き手の困りごと"},
   {en:"Solution and proof",ja:"解決と証拠"},
   {en:"Call to action",ja:"呼びかけ"},
   {en:"Networking: open, expand, connect, close",ja:"会話：話しかける→広げる→つなげる→締める"}
  ],
  phrases:[
   {en:"Have you ever stayed at a hotel where the staff remembered your name?",ja:"スタッフがあなたの名前を覚えていたホテルに泊まったことはありますか？",note:"問いかけのつかみ。答えを待つ間を1秒とる。"},
   {en:"Imagine a guest arriving after a ten-hour flight.",ja:"10時間のフライトのあとに到着したお客様を想像してください。",note:"Imagine... で場面に連れていく。"},
   {en:"Here's the problem.",ja:"問題はここです。",note:"つかみから本題への短い橋。"},
   {en:"Our solution is simple.",ja:"私たちの解決はシンプルです。",note:"解決に入る合図。むずかしく見せない。"},
   {en:"Please visit us at Booth 24 this afternoon.",ja:"今日の午後、24番のブースにお越しください。",note:"呼びかけは場所と時間をはっきり。"},
   {en:"Hi, I'm Akihiro. Did you enjoy the session?",ja:"こんにちは、章弘です。セッションはいかがでしたか？",note:"話しかけは軽く、短く。"},
   {en:"What brings you to this expo?",ja:"今日はどうしてこの展示会に？",note:"開いた質問で会話を広げる。"},
   {en:"That's interesting. Tell me more about your hotels.",ja:"おもしろいですね。ホテルのことをもっと聞かせてください。",note:"相手に多く話してもらう。"},
   {en:"I think there might be a good connection between our work.",ja:"私たちの仕事には、よいつながりがありそうです。",note:"接点を見つけて、つなげる。"},
   {en:"Here's my card. May I send you a short email next week?",ja:"名刺をどうぞ。来週、短いメールをお送りしてもいいですか？",note:"締めは、次の連絡の約束まで。"}
  ],
  model:{title:"ウェルネス展示会での3分ピッチと、ブースでの会話", time:"3分＋会話", note:"展示会の名前・ブースの番号・相手の仕事は練習用の例です。自分の場面に入れかえましょう。",
   lines:[
    {en:"[3-minute pitch] Good afternoon, everyone. Have you ever stayed at a hotel where the staff remembered your name?",ja:"［3分ピッチ］皆さん、こんにちは。スタッフがあなたの名前を覚えていたホテルに泊まったことはありますか？"},
    {en:"How did that feel? Special, right? You probably went back to that hotel.",ja:"どんな気持ちでしたか？ 特別ですよね。きっとそのホテルにまた行ったのではないでしょうか。"},
    {en:"My name is Akihiro Iwata. I'm a licensed acupuncturist and judo therapist from Japan.",ja:"岩田章弘と申します。日本から来た鍼灸師・柔道整復師です。"},
    {en:"Today I'd like to talk about one simple idea: guests come back when they feel cared for.",ja:"今日は、1つのシンプルな考えについてお話しします。お客様は、気にかけてもらえたと感じたときにもどってくる、ということです。"},
    {en:"Here's the problem. Many hotels and wellness centres spend a lot of money to find new guests.",ja:"問題はここです。多くのホテルやウェルネスセンターは、新しいお客様を見つけるために多くのお金を使っています。"},
    {en:"But they don't have a simple way to remember the guests they already have.",ja:"でも、すでにいるお客様を覚えておくかんたんな方法を持っていません。"},
    {en:"Imagine a guest arriving after a ten-hour flight. Her neck is stiff, and she is tired.",ja:"10時間のフライトのあとに到着したお客様を想像してください。首はこり、疲れています。"},
    {en:"If your staff notice this, and offer the right care, she will remember your hotel for years.",ja:"スタッフがそれに気づき、ぴったりのケアを申し出れば、その方は何年もあなたのホテルを覚えているでしょう。"},
    {en:"Our solution is simple. We combine three things.",ja:"私たちの解決はシンプルです。3つを組み合わせます。"},
    {en:"First, Japanese omotenashi: noticing what a guest needs before they ask.",ja:"1つめは日本のおもてなし。お客様が頼む前に、必要なことに気づくことです。"},
    {en:"Second, Japanese body care, from my work as a clinician and athletic trainer.",ja:"2つめは日本の体のケア。施術者とアスレティックトレーナーとしての私の仕事から来ています。"},
    {en:"Third, a simple booking and customer system that helps your staff remember each guest.",ja:"3つめは、スタッフが一人ひとりのお客様を覚えるのを助ける、かんたんな予約と顧客のしくみです。"},
    {en:"Is this just an idea? No. I run a clinic in Japan, and I check returning patients every day.",ja:"これはただの思いつきでしょうか。いいえ。私は日本で院を営み、毎日再来院を確認しています。"},
    {en:"I built this system for my own clinic, and now our partner clinics use it too.",ja:"このしくみは自分の院のために作り、今は提携院も使っています。"},
    {en:"Every morning, I look at three numbers: sales, visits and returning patients. The last one tells me if people feel cared for.",ja:"毎朝、売上・来院数・再来院の3つの数字を見ます。最後の数字が、人が気にかけてもらえたと感じているかを教えてくれます。"},
    {en:"Now I'd like to bring the same care to hotels and wellness centres in India.",ja:"今、同じケアを、インドのホテルやウェルネスセンターにお届けしたいと考えています。"},
    {en:"And if you'd like a Japanese evening for your guests, my family's sake shop, founded in 1957, can help too.",ja:"お客様のために日本の夜を開きたいときは、1957年創業の家族の酒店もお手伝いできます。"},
    {en:"So, here is my invitation. Please visit us at Booth 24 this afternoon.",ja:"そこで、ご案内です。今日の午後、24番のブースにお越しください。"},
    {en:"I'll show you the system, and I'll give you a short Japanese shoulder care session. It takes five minutes.",ja:"しくみをお見せし、日本の短い肩のケアを体験していただきます。5分で終わります。"},
    {en:"Guests come back when they feel cared for. Let's create that feeling together. Thank you.",ja:"お客様は、気にかけてもらえたと感じたときにもどってきます。その気持ちを一緒につくりましょう。ありがとうございました。"},
    {en:"[30-second version] Hi, I'm Akihiro Iwata, a licensed therapist from Japan.",ja:"［30秒の短い版］こんにちは、岩田章弘です。日本の資格を持つ施術者です。"},
    {en:"I help hotels and clinics in India welcome guests with Japanese omotenashi and body care.",ja:"インドのホテルやクリニックが、日本のおもてなしと体のケアでお客様を迎えるお手伝いをしています。"},
    {en:"I also offer a simple system that helps your staff remember each guest, so more guests come back.",ja:"また、スタッフが一人ひとりのお客様を覚えるのを助ける、かんたんなしくみもご提供しています。それで、もどってくるお客様がふえます。"},
    {en:"If that sounds interesting, I'd love to tell you more.",ja:"ご興味があれば、ぜひもっとお話しさせてください。"},
    {en:"[At the booth] Hi, I'm Akihiro. Did you enjoy the session?",ja:"［ブースで］こんにちは、章弘です。セッションはいかがでしたか？"},
    {en:"Thank you, I'm glad you liked the part about remembering names. What brings you to this expo?",ja:"ありがとうございます。名前を覚える話を気に入っていただけてうれしいです。今日はどうしてこの展示会に？"},
    {en:"Oh, you manage three boutique hotels in Jaipur. That's interesting. Tell me more about your hotels.",ja:"まあ、ジャイプールで3つの小さな高級ホテルを運営されているのですね。おもしろいですね。ホテルのことをもっと聞かせてください。"},
    {en:"So most of your guests are couples and families from abroad, and some come from Japan.",ja:"つまり、お客様の多くは海外からのカップルやご家族で、日本から来る方もいらっしゃるのですね。"},
    {en:"What's the biggest challenge for your team at the moment?",ja:"今、チームにとっていちばんの課題は何ですか？"},
    {en:"I see. Your staff are friendly, but they find it hard to know what Japanese guests really want.",ja:"なるほど。スタッフは親しみやすいけれど、日本のお客様が本当に望んでいることがわかりにくい、ということですね。"},
    {en:"Japanese guests often don't say what they need. They expect you to notice.",ja:"日本のお客様は、必要なことを口に出さないことが多いです。気づいてもらえることを期待しています。"},
    {en:"For example, they may want a quiet room, or simple instructions in Japanese, but they won't complain.",ja:"たとえば、静かな部屋や、日本語のかんたんな説明がほしくても、不満を言わないのです。"},
    {en:"I think there might be a good connection between our work.",ja:"私たちの仕事には、よいつながりがありそうです。"},
    {en:"A short training on Japanese guests could help your staff feel more confident.",ja:"日本のお客様についての短い研修で、スタッフの皆さんがもっと自信を持てるかもしれません。"},
    {en:"Would you like to try the shoulder care now? It only takes five minutes.",ja:"今、肩のケアを試してみませんか？ 5分しかかかりません。"},
    {en:"Great. While we do that, I can show you the booking system on this tablet.",ja:"よかった。その間に、このタブレットで予約のしくみをお見せできます。"},
    {en:"How does your shoulder feel now? Lighter? I'm glad to hear that.",ja:"肩の具合はいかがですか？ 軽くなりましたか？ それはよかったです。"},
    {en:"Here's my card. May I send you a short email next week?",ja:"名刺をどうぞ。来週、短いメールをお送りしてもいいですか？"},
    {en:"I'll include a one-page summary and a few ideas for your Japanese guests.",ja:"1枚のまとめと、日本のお客様のためのいくつかのアイデアを入れます。"},
    {en:"If it's helpful, we could have a short online call after that.",ja:"お役に立ちそうなら、そのあと短いオンラインの打ち合わせもできます。"},
    {en:"Thank you so much for stopping by. It was really nice to meet you. Enjoy the rest of the expo.",ja:"お立ち寄りいただき、本当にありがとうございました。お会いできてうれしかったです。展示会の残りもお楽しみください。"},
    {en:"[Introducing someone] Excuse me, may I introduce you to someone? This is Ms. Rao. She runs a yoga studio in Pune.",ja:"［人を紹介する］失礼します、ご紹介してもよろしいですか？ こちらはラオさん。プネーでヨガのスタジオを営んでいます。"},
    {en:"Ms. Rao, this is the hotel manager from Jaipur I mentioned. She is looking for wellness programs for her guests.",ja:"ラオさん、こちらが先ほどお話ししたジャイプールのホテルのマネージャーです。お客様のためのウェルネスのプログラムを探しています。"},
    {en:"I think you two might have a lot to talk about. Yoga in the morning and Japanese care in the evening could be a nice combination.",ja:"お二人は話すことがたくさんありそうです。朝はヨガ、夜は日本のケア、というのはよい組み合わせかもしれません。"},
    {en:"I'll leave you to talk. Please let me know if I can help with anything.",ja:"ではお二人でどうぞ。何かお手伝いできることがあれば、お知らせください。"},
    {en:"[Closing the day] Thank you for coming to the booth today, everyone. We met many wonderful people.",ja:"［1日の締め］今日はブースにお越しいただき、皆さんありがとうございました。すばらしい方々にたくさんお会いできました。"},
    {en:"I'll send each of you a short email within two days, as I promised.",ja:"お約束どおり、2日以内に皆さん一人ひとりに短いメールをお送りします。"},
    {en:"Remember, guests come back when they feel cared for. I hope we can create that feeling together in India.",ja:"お客様は、気にかけてもらえたと感じたときにもどってきます。インドでその気持ちを一緒につくれたらうれしいです。"}
   ]},
  task:"インドのウェルネス・ホスピタリティの展示会で、3分ピッチ（つかみ→困りごと→解決→証拠→呼びかけ）をし、そのあとブースで1人と、話しかける→広げる→つなげる→締める の流れで会話する。30秒の短い版も言えるようにする。",
  taskEn:"Give a 3-minute pitch at a wellness and hospitality expo in India (hook, problem, solution, proof, call to action). Then have a networking conversation with me at your booth. Also prepare a 30-second version.",
  qa:[
   {q:"I only have a minute. What exactly do you do?",a:"In one sentence: I help hotels and clinics in India bring guests back with Japanese care, omotenashi and a simple customer system.",ja:"1分しかありません。あなたは具体的に何をしているのですか？／ひとことで言うと、日本のケア、おもてなし、かんたんな顧客のしくみで、インドのホテルやクリニックにお客様がもどってくるお手伝いをしています。"},
   {q:"Do you have any clients in India yet?",a:"I'm building partnerships in India now, and I visit regularly. In Japan, our partner clinics use the system. I'd be happy to start with a small pilot.",ja:"インドにはもう顧客がいますか？／今インドで提携を作っているところで、定期的に来ています。日本では提携院がしくみを使っています。小さな試行から始められればうれしいです。"},
   {q:"Can I bring my operations manager to your booth later?",a:"Of course. I'll be at Booth 24 until five o'clock. Please come any time.",ja:"あとで運営の責任者をブースに連れてきてもいいですか？／もちろんです。5時まで24番のブースにいます。いつでもどうぞ。"},
   {q:"Are you also selling sake here?",a:"Not today. But my family's sake shop exports to partners overseas. If you're interested, I can send you some information.",ja:"ここで日本酒も売っているのですか？／今日は売っていません。でも、家族の酒店が海外のパートナーに日本酒を出しています。ご興味があれば、資料をお送りします。"}
  ],
  check:[
   "3分ピッチの最初の15秒で、問いかけか場面のつかみを入れられたか",
   "最後の呼びかけで、場所と時間をはっきり言えたか",
   "30秒の短い版を、何も見ずに言えたか",
   "ブースでの会話で、自分より相手に多く話してもらえたか",
   "名刺交換のあと、次に連絡する約束までできたか"
  ],
  slide:"3分ピッチのスライドは3〜4枚。1枚めは問いかけの一文だけ、最後の1枚はブースの番号と時間を大きく書きましょう。"},
 {week:50, level:"B2", length:"7分", title:"プレゼン後のフォローアップ",
  skill:"プレゼンや会議のあとに、決まったこと・アクションアイテム（誰が・何を・いつまでに）・次の一歩を、まとめのスライドとメールで7分で伝えられる。",
  lesson:[
   "プレゼンは、話し終わったら終わりではありません。本当に大切なのは、そのあとのフォローアップです。数日たつと、聞き手は話の中身の多くを忘れてしまいます。そこで、プレゼンのあと1〜2日以内に、「まとめのスライド」と「フォローアップのメール」で、決まったことと次の一歩を形に残します。",
   "まとめの順番は、①お礼 ②決まったこと（Decisions）③アクションアイテム（Action items：誰が・何を・いつまでに）④まだ決まっていないこと（Open questions）⑤次の会議、です。アクションアイテムは、Akihiro will send the training plan by 15 March. のように、人の名前・動詞・期限を必ず1文に入れます。「誰かがやるだろう」をなくすのが目的です。",
   "オンライン会議でまとめを話すときは、画面を共有して、1行ずつ読み上げながら Is that correct? と確かめます。まちがいがあれば、その場で直しましょう。Let me share my screen.（画面を共有します）、Can everyone see my screen?（画面は見えていますか？）もよく使う言い方です。メールの件名は Follow-up: ... のように、ひと目でわかるものにします。",
   "今週の手本は、インドのホテルとの提携の打ち合わせのあと、オンラインでまとめのスライドを見せながら、決まったこととアクションアイテムを確認し、最後にフォローアップのメールの中身を伝える話です。日付・人の名前・数字は練習用の例です。"
  ],
  structure:[
   {en:"Thanks and purpose",ja:"お礼と目的"},
   {en:"Decisions",ja:"決まったこと"},
   {en:"Action items (who, what, when)",ja:"アクションアイテム（誰が・何を・いつまでに）"},
   {en:"Open questions",ja:"まだ決まっていないこと"},
   {en:"Next meeting and follow-up email",ja:"次の会議とフォローアップのメール"}
  ],
  phrases:[
   {en:"Thank you again for your time last Tuesday.",ja:"先週の火曜日は、お時間をいただき改めてありがとうございました。",note:"フォローアップは、まずお礼から。"},
   {en:"Let me share my screen. Can everyone see it?",ja:"画面を共有します。皆さん見えていますか？",note:"オンライン会議の決まり文句。"},
   {en:"I'd like to quickly go over what we agreed.",ja:"合意したことを手短に確認したいと思います。",note:"go over = ざっと確認する。"},
   {en:"We agreed to start with a three-month pilot.",ja:"3か月の試行から始めることで合意しました。",note:"決まったことは agreed to で。"},
   {en:"Here are the action items.",ja:"アクションアイテムはこちらです。",note:"誰が・何を・いつまでに、の一覧に入る合図。"},
   {en:"I will send the training plan by 15 March.",ja:"私が3月15日までに研修の計画をお送りします。",note:"名前（主語）・動詞・期限を必ず1文に。"},
   {en:"Could you confirm the training dates by the end of next week?",ja:"来週末までに、研修の日程を確定していただけますか？",note:"相手のアクションも、ていねいに期限つきで。"},
   {en:"One question is still open.",ja:"1つ、まだ決まっていないことがあります。",note:"決まっていないことも、かくさず残す。"},
   {en:"Did I miss anything?",ja:"何か抜けていることはありますか？",note:"まとめの最後に必ず聞く。"},
   {en:"I'll send you a follow-up email with this summary today.",ja:"今日中に、このまとめをフォローアップのメールでお送りします。",note:"口で言ったことを、必ず文字に残す。"}
  ],
  model:{title:"提携の打ち合わせのあとのまとめ（オンライン・7分）", time:"7分", note:"日付・人の名前・数字は練習用の例です。自分の内容に入れかえましょう。",
   lines:[
    {en:"Hello, everyone. Thank you again for your time last Tuesday in Bengaluru.",ja:"皆さん、こんにちは。先週の火曜日は、ベンガルールでお時間をいただき改めてありがとうございました。"},
    {en:"I really enjoyed our discussion, and I learned a lot from your questions.",ja:"話し合いはとても楽しく、皆さんのご質問から多くを学びました。"},
    {en:"Today I'd like to quickly go over what we agreed, and make sure everyone knows the next steps.",ja:"今日は、合意したことを手短に確認し、皆さんが次の一歩をわかっているかを確かめたいと思います。"},
    {en:"It will take about seven minutes. Let me share my screen. Can everyone see it?",ja:"7分ほどです。画面を共有します。皆さん見えていますか？"},
    {en:"Great. This slide has four parts: decisions, action items, open questions, and our next meeting.",ja:"よかったです。このスライドには4つの部分があります。決まったこと、アクションアイテム、まだ決まっていないこと、次の会議です。"},
    {en:"Let me start with the decisions. We made three decisions last week.",ja:"まず決まったことから。先週、3つのことを決めました。"},
    {en:"First, we agreed to start with a three-month pilot at your hotel in Bengaluru.",ja:"1つめ、ベンガルールのホテルで3か月の試行から始めることで合意しました。"},
    {en:"Second, the pilot will include hospitality training, short care sessions for guests, and the booking system.",ja:"2つめ、試行には、おもてなし研修、お客様向けの短いケア、予約のしくみが含まれます。"},
    {en:"Third, we will hold one Japanese evening with sake for your guests during the pilot.",ja:"3つめ、試行の間に、お客様のための日本酒を楽しむ日本の夜を1回開きます。"},
    {en:"Is that correct? Good. Thank you, Mr. Mehta.",ja:"合っていますか？ よかったです。メータさん、ありがとうございます。"},
    {en:"Moving on to the action items. This is the most important part of today's call.",ja:"アクションアイテムに移ります。ここが今日の打ち合わせでいちばん大切なところです。"},
    {en:"For each item, I've written who will do it, what they will do, and by when.",ja:"それぞれの項目に、誰が、何を、いつまでにするかを書きました。"},
    {en:"I learned this from running my clinic. If a task has no name and no date, it usually doesn't happen.",ja:"これは院の経営から学びました。名前と期日のない仕事は、たいてい進みません。"},
    {en:"So please check your name carefully, and tell me if a date is not realistic.",ja:"ですから、ご自分の名前をよく確かめ、期日が無理なら教えてください。"},
    {en:"It's much better to change a date today than to miss it later.",ja:"あとで期日に遅れるより、今日期日を変えるほうがずっとよいのです。"},
    {en:"Here are the action items. There are six in total, three for my team and three for yours.",ja:"アクションアイテムはこちらです。全部で6つ、私のチームが3つ、皆さんのチームが3つです。"},
    {en:"Number one. I will send the training plan by 15 March.",ja:"1番。私が3月15日までに研修の計画をお送りします。"},
    {en:"It will include the schedule for the two training days and the topics for each session.",ja:"2日間の研修の日程と、それぞれの時間の内容が入ります。"},
    {en:"Number two. My team will set up the booking system and send you a test account by 20 March.",ja:"2番。私のチームが予約のしくみを準備し、3月20日までに試し用のアカウントをお送りします。"},
    {en:"Number three. I will send a short list of sake for the Japanese evening, with prices, by the end of March.",ja:"3番。私が3月末までに、日本の夜のための日本酒の短い一覧を、価格つきでお送りします。"},
    {en:"Now, the items for your team. Number four. Could you confirm the training dates by the end of next week?",ja:"次に、皆さんのチームの項目です。4番。来週末までに、研修の日程を確定していただけますか？"},
    {en:"Ms. Iyer, you mentioned that you would check the staff schedule. Is that still fine for you?",ja:"アイヤーさん、スタッフの勤務表を確認するとおっしゃっていましたね。それで今も大丈夫でしょうか？"},
    {en:"Thank you. Number five. Could your team prepare the guest messages in Hindi by 25 March?",ja:"ありがとうございます。5番。3月25日までに、お客様へのヒンディー語のメッセージを用意していただけますか？"},
    {en:"We will send you the English version first, so you only need to translate it.",ja:"先に英語版をお送りしますので、訳していただくだけで大丈夫です。"},
    {en:"Number six. Could you introduce us to your importer, so we can start the sake paperwork?",ja:"6番。日本酒の書類の手続きを始められるように、輸入業者の方をご紹介いただけますか？"},
    {en:"Mr. Mehta said he would do this. Is there a date that works for you?",ja:"メータさんがしてくださるとのことでした。ご都合のよい期日はありますか？"},
    {en:"By 18 March? Perfect. I'll add that to the list now.",ja:"3月18日までですね。ありがとうございます。今、一覧に加えます。"},
    {en:"So, to repeat, everyone now has a clear task and a clear date.",ja:"くり返すと、これで全員に、はっきりした役目と期日があります。"},
    {en:"That brings me to the open questions. One question is still open.",ja:"そこで、まだ決まっていないことの話になります。1つ、まだ決まっていないことがあります。"},
    {en:"We haven't decided the price for guests who book the short care session.",ja:"短いケアを予約するお客様への料金が、まだ決まっていません。"},
    {en:"Last week, we discussed two options: including it in the room price, or charging it separately.",ja:"先週、2つの案を話し合いました。部屋の料金に含めるか、別にいただくかです。"},
    {en:"I suggest we decide this at our next meeting, after your team checks the room prices.",ja:"皆さんのチームが部屋の料金を確認したあと、次の会議で決めることをご提案します。"},
    {en:"Does everyone agree? Thank you.",ja:"皆さん、よろしいでしょうか？ ありがとうございます。"},
    {en:"There is also one small point from the Q&A. Someone asked about examples from other projects in India.",ja:"質疑応答からの小さな点も1つあります。インドでのほかの事例について、ご質問がありました。"},
    {en:"I promised to answer by Friday, and I sent the information yesterday. Please let me know if you didn't receive it.",ja:"金曜までにお答えするとお約束し、昨日情報をお送りしました。届いていなければお知らせください。"},
    {en:"Finally, our next meeting. I suggest a short online call on 28 March, at 3 p.m. India time.",ja:"最後に、次の会議です。3月28日、インド時間の午後3時に、短いオンラインの打ち合わせをご提案します。"},
    {en:"That's 6:30 p.m. in Japan, so it works well for me.",ja:"日本では午後6時30分なので、私にとっても都合がよいです。"},
    {en:"In that meeting, we'll check the action items and decide the price for the care session.",ja:"その会議では、アクションアイテムを確認し、ケアの料金を決めます。"},
    {en:"Let me sum up. We have three decisions, six action items, one open question, and one next meeting.",ja:"まとめます。決まったことが3つ、アクションアイテムが6つ、まだ決まっていないことが1つ、そして次の会議が1つです。"},
    {en:"Did I miss anything? Please tell me now, and I'll add it.",ja:"何か抜けていることはありますか？ 今おっしゃっていただければ、加えます。"},
    {en:"Ah, yes, thank you, Ms. Iyer. The training room needs a projector. I'll add that to your team's list.",ja:"ああ、そうですね。アイヤーさん、ありがとうございます。研修の部屋にプロジェクターが必要ですね。皆さんのチームの一覧に加えます。"},
    {en:"I'll send you a follow-up email with this summary today.",ja:"今日中に、このまとめをフォローアップのメールでお送りします。"},
    {en:"The subject will be: Follow-up: Bengaluru pilot, decisions and action items.",ja:"件名は「フォローアップ：ベンガルールの試行、決まったこととアクションアイテム」です。"},
    {en:"The email will have the same four parts as this slide, so it's easy to check later.",ja:"メールはこのスライドと同じ4つの部分にしますので、あとで確認しやすいはずです。"},
    {en:"I'll also attach the slides from last week's presentation.",ja:"先週のプレゼンのスライドも添付します。"},
    {en:"Let me read you the first lines of the email, so you know what to expect.",ja:"どんなメールが届くかわかるように、最初の数行を読み上げます。"},
    {en:"Dear all, thank you for a productive meeting. Please find below a summary of our decisions and action items.",ja:"皆さま、実りある会議をありがとうございました。決まったことと、アクションアイテムのまとめを以下にお送りします。"},
    {en:"Each action item shows the owner and the deadline. Please let me know by Friday if anything needs to be corrected.",ja:"それぞれのアクションアイテムには、担当と期日を書いています。直す点があれば、金曜までにお知らせください。"},
    {en:"Short and clear. That's all.",ja:"短く、はっきりと。それだけです。"},
    {en:"If anything changes, please reply to that email, so that everyone can see the update.",ja:"何か変わったら、そのメールに返信してください。そうすれば全員が最新の状況を見られます。"},
    {en:"Thank you all very much. I'm really looking forward to starting the pilot with you.",ja:"皆さん、本当にありがとうございました。皆さんと試行を始めるのを、とても楽しみにしています。"}
   ]},
  task:"インドのホテルとの打ち合わせのあと、オンラインで、まとめのスライドを見せながら、決まったこと・アクションアイテム（誰が・何を・いつまでに）・まだ決まっていないこと・次の会議を7分で確認する。そのあと同じ中身のフォローアップのメールを書く。",
  taskEn:"Lead a 7-minute online follow-up call after a partnership meeting with a hotel in India. Share a summary slide and go over decisions, action items (who, what, by when), open questions and the next meeting. Then write the follow-up email.",
  qa:[
   {q:"Can we move the training plan deadline to 20 March?",a:"Of course. I'll change it to 20 March and update the list in the follow-up email.",ja:"研修計画の期限を3月20日にずらせますか？／もちろんです。3月20日に変えて、フォローアップのメールの一覧を直します。"},
   {q:"Who should we contact if the test account doesn't work?",a:"Please contact me directly by email. I'll reply within one working day, and my team will fix it.",ja:"試し用のアカウントが動かないとき、誰に連絡すればいいですか？／私に直接メールでご連絡ください。1営業日以内にお返事し、私のチームが直します。"},
   {q:"Could you also send the summary to our general manager?",a:"Certainly. Could you share his email address? I'll add him to the follow-up email.",ja:"まとめを総支配人にも送っていただけますか？／もちろんです。メールアドレスを教えていただけますか？ フォローアップのメールに加えます。"},
   {q:"What if we can't finish the Hindi messages by 25 March?",a:"That's fine. We can start with English and Japanese, and add Hindi later. It won't delay the pilot.",ja:"3月25日までにヒンディー語のメッセージが終わらなかったら？／大丈夫です。英語と日本語で始めて、あとでヒンディー語を加えられます。試行が遅れることはありません。"}
  ],
  check:[
   "決まったこと・アクションアイテム・まだ決まっていないこと・次の会議の4つの順で話せたか",
   "アクションアイテムの1文1文に、誰が・何を・いつまでにを入れられたか",
   "1つずつ Is that correct? などで確かめ、まちがいをその場で直せたか",
   "最後に Did I miss anything? と聞けたか",
   "口で言ったことを、同じ形のフォローアップのメールに書けたか"
  ],
  slide:"まとめのスライドは表にして、アクションアイテムを「Who / What / By when」の3列で並べます。自分のチームと相手のチームの行は色を分けましょう。"},
 {week:51, level:"B2", length:"8分", title:"チームの前で話す",
  skill:"チームのキックオフで、目的を示し、やわらかく指示を出し、前向きなフィードバックと励ましで、8分のリーダーとしてのスピーチができる。",
  lesson:[
   "今週は、お客様ではなく「一緒に働くチーム」の前で話す練習です。プロジェクトの始まり（キックオフ）では、リーダーの話がチームの気持ちを決めます。順番は、①お礼と歓迎 ②なぜこれをするのか（目的）③何をするのか（役割と指示）④どうやって支えるか ⑤励ましと決意、です。最初に「なぜ」を話すと、人は自分から動きたくなります。",
   "指示は、命令の形（Do this.）ではなく、やわらかい形で出します。Could you...?（〜してもらえますか）、I'd like you to...（〜してほしいです）、Let's...（〜しましょう）、The first thing we need to do is...（最初にすることは〜です）。インドでも日本でも、ていねいな頼み方のほうが、チームは気持ちよく動いてくれます。ただし、大事な決まり（安全や時間）は、It's very important that... とはっきり言いましょう。",
   "フィードバックは「よかった点 → 次に試すこと → 励まし」の順にします。I really liked how you... / Next time, you could try... / I know you can do it. のように言うと、相手は前向きに受け取れます。全員の前ではほめ、直してほしいことは個別に伝えるのが基本です。",
   "8分の話は、長く感じられがちです。途中で聞き手に手を挙げてもらったり、隣の人と30秒話してもらったりすると、集中が続きます。今週の手本は、インドのホテルで試行が始まる日に、スタッフの皆さんの前で話すキックオフのスピーチです。人数・日程・名前は練習用の例です。"
  ],
  structure:[
   {en:"Welcome and thanks",ja:"歓迎とお礼"},
   {en:"Why we are doing this",ja:"なぜこれをするのか（目的）"},
   {en:"Roles and instructions",ja:"役割と指示"},
   {en:"How I will support you (feedback)",ja:"どう支えるか（フィードバック）"},
   {en:"Encouragement and commitment",ja:"励ましと決意"}
  ],
  phrases:[
   {en:"Welcome, everyone. I'm so glad to be working with you.",ja:"皆さん、ようこそ。一緒に働けて本当にうれしいです。",note:"キックオフの最初のひとこと。笑顔で。"},
   {en:"Before we talk about what to do, I want to talk about why.",ja:"何をするかの前に、なぜするのかをお話ししたいと思います。",note:"「なぜ」を先に話すと、人は動きたくなる。"},
   {en:"The first thing we need to do is learn each guest's name.",ja:"最初にすることは、一人ひとりのお客様の名前を覚えることです。",note:"指示を「最初の一歩」として示す。"},
   {en:"Could you greet every guest within ten seconds of arrival?",ja:"お客様が到着して10秒以内に、全員にあいさつしてもらえますか？",note:"Could you...? で、やわらかい指示。"},
   {en:"I'd like each team to choose one leader.",ja:"それぞれのチームに、リーダーを1人決めてほしいです。",note:"I'd like you to... と同じく、ていねいな指示。"},
   {en:"It's very important that we never rush a guest.",ja:"お客様を決して急がせないことが、とても大切です。",note:"大事な決まりは、はっきりと。"},
   {en:"I really liked how you welcomed the guest this morning.",ja:"今朝のお客様の迎え方、とてもよかったです。",note:"フィードバックは、よかった点から。"},
   {en:"Next time, you could try using the guest's name once more.",ja:"次は、お客様の名前をもう一度呼んでみるといいですね。",note:"直す点は「次に試すこと」として。"},
   {en:"Mistakes are fine. They're how we learn.",ja:"まちがいは大丈夫です。それが学び方です。",note:"失敗をこわがらない空気をつくる。"},
   {en:"I believe in this team. Let's do this together.",ja:"私はこのチームを信じています。一緒にやりましょう。",note:"締めは、信頼と「一緒に」を。"}
  ],
  model:{title:"インドのホテルでの試行のキックオフ・スピーチ（8分）", time:"8分", note:"人数・日程・名前・数字は練習用の例です。自分の場面に入れかえましょう。",
   lines:[
    {en:"Good morning, everyone. Namaste. Welcome, and thank you for coming in early today.",ja:"皆さん、おはようございます。ナマステ。ようこそ。今日は早く来てくださって、ありがとうございます。"},
    {en:"I'm Akihiro Iwata. Many of you met me last month, but some of you are new, so let me say hello again.",ja:"岩田章弘です。先月お会いした方も多いですが、初めての方もいるので、もう一度ごあいさつします。"},
    {en:"I'm so glad to be working with you. Today is the first day of our three-month pilot.",ja:"皆さんと一緒に働けて本当にうれしいです。今日は、3か月の試行の初日です。"},
    {en:"I'll speak for about eight minutes. Then we'll start the first training session.",ja:"8分ほどお話しします。そのあと、最初の研修を始めます。"},
    {en:"Before we talk about what to do, I want to talk about why.",ja:"何をするかの前に、なぜするのかをお話ししたいと思います。"},
    {en:"Let me ask you a question. Please raise your hand if you have ever been a guest somewhere and felt truly cared for.",ja:"1つ質問させてください。どこかでお客として、本当に大切にしてもらえたと感じたことがある方は、手を挙げてください。"},
    {en:"Almost everyone. Thank you. Now think about that moment for a few seconds.",ja:"ほとんど全員ですね。ありがとうございます。では、数秒その時のことを思い出してください。"},
    {en:"How did you feel? Happy, relaxed, and maybe a little surprised.",ja:"どんな気持ちでしたか？ うれしくて、ほっとして、少し驚いたかもしれません。"},
    {en:"Please turn to the person next to you and share that moment in thirty seconds.",ja:"隣の人のほうを向いて、その時のことを30秒で話してみてください。"},
    {en:"Thank you. I heard some lovely stories. That feeling is exactly why we are here.",ja:"ありがとうございます。すてきなお話が聞こえました。その気持ちこそが、私たちがここにいる理由です。"},
    {en:"Our goal is simple. We want every guest to leave this hotel with that feeling.",ja:"私たちの目標はシンプルです。すべてのお客様に、その気持ちを持ってこのホテルを出ていただくことです。"},
    {en:"In India, you already have a beautiful tradition of hospitality. In Japan, we call our tradition omotenashi.",ja:"インドには、すでにすばらしいもてなしの伝統があります。日本では、私たちの伝統をおもてなしと呼びます。"},
    {en:"In this pilot, we will bring the two together. We are not replacing what you do. We are adding to it.",ja:"この試行では、その2つを合わせます。皆さんのやり方を置きかえるのではありません。そこに加えるのです。"},
    {en:"Moving on to what we will do. I'd like to give you three simple instructions.",ja:"何をするかに移ります。3つのかんたんなお願いをしたいと思います。"},
    {en:"The first thing we need to do is learn each guest's name, and use it.",ja:"最初にすることは、一人ひとりのお客様の名前を覚えて、呼ぶことです。"},
    {en:"The booking system will show you the name, the room and any notes before the guest arrives.",ja:"予約のしくみが、お客様の到着前に、名前、部屋、メモを見せてくれます。"},
    {en:"Could you check the system at the start of every shift? It only takes five minutes.",ja:"毎回の勤務の始めに、しくみを確認してもらえますか？ 5分しかかかりません。"},
    {en:"Second, could you greet every guest within ten seconds of arrival? A smile and a few warm words are enough.",ja:"2つめ、お客様が到着して10秒以内に、全員にあいさつしてもらえますか？ 笑顔と温かいひとことで十分です。"},
    {en:"Third, notice one small thing about each guest, and write it in the system.",ja:"3つめ、お客様一人ひとりについて小さなことを1つ見つけて、しくみに書いてください。"},
    {en:"For example, the guest prefers green tea, or the guest looked tired after the flight.",ja:"たとえば、そのお客様は緑茶が好き、フライトのあと疲れた様子だった、などです。"},
    {en:"These notes are how we remember people. They are the heart of this project.",ja:"こうしたメモが、人を覚える方法です。このプロジェクトの心臓部です。"},
    {en:"Imagine the same guest comes back next year. The front desk says, welcome back, and a cup of green tea is already waiting.",ja:"同じお客様が来年またいらしたと想像してください。フロントが「おかえりなさい」と言い、緑茶がもう用意されています。"},
    {en:"That guest will tell friends about this hotel. That's how one small note becomes new guests.",ja:"そのお客様は、友だちにこのホテルのことを話すでしょう。こうして、1つの小さなメモが新しいお客様につながるのです。"},
    {en:"In my clinic in Japan, I look at the rate of returning patients every day. It tells me whether people felt cared for.",ja:"日本の私の院では、毎日再来院率を見ています。人が大切にされたと感じたかどうかを教えてくれるからです。"},
    {en:"In this pilot, we'll watch a similar number: how many guests come back, and what they write in their reviews.",ja:"この試行では、似た数字を見ます。どれだけのお客様がもどってくるか、そして口コミに何と書くかです。"},
    {en:"Now, roles. We have twenty staff in this pilot, so I'd like to make four teams of five.",ja:"次に役割です。この試行には20人のスタッフがいるので、5人ずつ4つのチームを作りたいと思います。"},
    {en:"The front desk team, the therapy team, the restaurant team, and the guest relations team.",ja:"フロントのチーム、セラピーのチーム、レストランのチーム、そしてお客様担当のチームです。"},
    {en:"I'd like each team to choose one leader by the end of today.",ja:"それぞれのチームに、今日中にリーダーを1人決めてほしいです。"},
    {en:"Team leaders will meet with me for fifteen minutes every Friday to share what's working and what isn't.",ja:"チームリーダーは毎週金曜に15分、私と集まり、うまくいっていることといないことを共有します。"},
    {en:"There is one rule I'd like everyone to remember. It's very important that we never rush a guest.",ja:"全員に覚えておいてほしい決まりが1つあります。お客様を決して急がせないことが、とても大切です。"},
    {en:"Even when we are busy, the guest in front of us should feel like the only guest.",ja:"忙しいときでも、目の前のお客様には、自分だけのお客だと感じていただくべきです。"},
    {en:"This is the most important lesson I've learned in my work. Give your full effort to the person in front of you.",ja:"これは、私が仕事で学んだいちばん大切なことです。目の前の人に全力を尽くすこと。"},
    {en:"When I worked as an athletic trainer, I learned that small, careful habits make a big difference over a season.",ja:"アスレティックトレーナーをしていたとき、小さくてていねいな習慣が、1シーズンで大きなちがいを生むことを学びました。"},
    {en:"It's the same in a hotel. Small habits, every day, for three months.",ja:"ホテルでも同じです。小さな習慣を、毎日、3か月間。"},
    {en:"That brings me to how I will support you.",ja:"そこで、私が皆さんをどう支えるかの話になります。"},
    {en:"During the first two weeks, I'll be here at the hotel. I'll watch, help and give feedback.",ja:"最初の2週間は、私がホテルにいます。見て、手伝い、フィードバックをします。"},
    {en:"My feedback will always have three parts: what went well, what to try next, and encouragement.",ja:"私のフィードバックは、いつも3つの部分でできています。よかったこと、次に試すこと、そして励ましです。"},
    {en:"For example, I might say: I really liked how you welcomed the guest this morning.",ja:"たとえば、こう言うかもしれません。今朝のお客様の迎え方、とてもよかったです。"},
    {en:"Next time, you could try using the guest's name once more when they leave.",ja:"次は、お客様が出られるときに、もう一度名前を呼んでみるといいですね。"},
    {en:"And then, I know you can do it.",ja:"そして、あなたならできます、と。"},
    {en:"I will praise you in front of the team. If I have a suggestion, I'll tell you privately.",ja:"ほめるときはチームの前で。提案があるときは、個別にお伝えします。"},
    {en:"Team leaders, could you also give feedback to your own team in the same way? Start with something good.",ja:"チームリーダーの皆さん、自分のチームにも同じやり方でフィードバックしてもらえますか？ よいことから始めてください。"},
    {en:"After two weeks, I'll support you online every week, and I'll come back for the review at the end.",ja:"2週間後は、毎週オンラインで支え、最後の見直しのときにまたうかがいます。"},
    {en:"I also want to hear from you. If something doesn't work, please tell me. You know this hotel better than I do.",ja:"皆さんの声も聞きたいです。うまくいかないことがあれば教えてください。このホテルのことは、皆さんのほうがよくご存じです。"},
    {en:"Mistakes are fine. They're how we learn. I make mistakes too, especially in English.",ja:"まちがいは大丈夫です。それが学び方です。私もまちがえます。特に英語で。"},
    {en:"English is not my first language. If I don't understand you, I'll ask again, and I hope you'll do the same with me.",ja:"英語は私の母語ではありません。わからないときは聞き返しますので、皆さんも私に同じようにしてください。"},
    {en:"Asking again is not a weakness. It shows that we care about getting things right.",ja:"聞き返すのは弱さではありません。正しく伝えることを大切にしている証です。"},
    {en:"So please don't be afraid to try. A guest will always forgive a kind mistake.",ja:"ですから、こわがらずに試してください。やさしさから出たまちがいなら、お客様はいつでも許してくださいます。"},
    {en:"Let me sum up. We are here so that every guest feels truly cared for.",ja:"まとめます。私たちがここにいるのは、すべてのお客様に本当に大切にされたと感じていただくためです。"},
    {en:"We have three habits: use the guest's name, greet within ten seconds, and note one small thing.",ja:"習慣は3つ。お客様の名前を呼ぶ、10秒以内にあいさつする、小さなことを1つ書く。"},
    {en:"We have one rule: never rush a guest. And we have four teams, each with a leader.",ja:"決まりは1つ。お客様を決して急がせない。そして、リーダーのいる4つのチームがあります。"},
    {en:"Three months is not a long time. But if we do these small things every day, the guests will feel the difference.",ja:"3か月は長くありません。でも、こうした小さなことを毎日続ければ、お客様はちがいを感じてくださいます。"},
    {en:"And I'm sure you'll feel proud of what we build together.",ja:"そして、一緒につくるものに、きっと皆さんは誇りを感じるはずです。"},
    {en:"I believe in this team. Let's do this together.",ja:"私はこのチームを信じています。一緒にやりましょう。"},
    {en:"Now, let's take a five-minute break, and then we'll start the first session in the training room.",ja:"では、5分休憩して、そのあと研修の部屋で最初の時間を始めましょう。"},
    {en:"Thank you, everyone. Dhanyavaad.",ja:"皆さん、ありがとうございました。ダンニャワード。"}
   ]},
  task:"インドのホテルで試行が始まる日に、20人のスタッフの前で、目的（なぜ）・3つの指示・役割・支え方・励ましを入れたキックオフのスピーチを8分で行う。途中で1回、聞き手に参加してもらう。",
  taskEn:"Give an 8-minute kickoff speech to twenty hotel staff in India on the first day of a pilot. Explain why, give three soft instructions, explain roles and how you will support them, and finish with encouragement. Include one moment where the audience takes part.",
  qa:[
   {q:"What should we do if a guest doesn't want to talk?",a:"Good question. Then we respect that. A quiet smile is also omotenashi. Just write a note, like 'prefers quiet', in the system.",ja:"お客様が話したくなさそうなときは、どうすればいいですか？／よい質問です。その場合はその気持ちを大切にします。静かな笑顔もおもてなしです。しくみに「静かなのを好む」のようにメモしておきましょう。"},
   {q:"We are very busy at check-out time. How can we never rush a guest?",a:"I understand. When it's busy, we can't make it slower, but we can make it warmer. Use the guest's name, and say thank you while looking at them.",ja:"チェックアウトの時間はとても忙しいです。どうしたら急がせずにすみますか？／わかります。忙しいときに時間を延ばすことはできませんが、温かくすることはできます。お客様の名前を呼び、目を見てありがとうと言いましょう。"},
   {q:"Will this mean more work for us?",a:"At first, a little. But after two weeks, these habits will feel natural, and the system will save you time when guests come back.",ja:"これで私たちの仕事はふえますか？／最初は少しふえます。でも2週間たてば習慣が自然になり、お客様がもどってきたとき、しくみが時間を節約してくれます。"},
   {q:"How will you choose the best team at the end?",a:"I won't choose a winner. All four teams need each other. But we will celebrate the best moments together at the review.",ja:"最後にいちばんよいチームをどう選ぶのですか？／勝ち負けは決めません。4つのチームはお互いに必要です。でも見直しのとき、いちばんよかった場面を一緒にお祝いします。"}
  ],
  check:[
   "最初に「なぜ」を話してから、「何を」に入れたか",
   "指示を Could you...? / I'd like you to... / Let's... のやわらかい形で出せたか",
   "大事な決まりは It's very important that... ではっきり言えたか",
   "フィードバックを「よかった点→次に試すこと→励まし」の順で例に出せたか",
   "途中で1回、聞き手に手を挙げる・隣と話すなどで参加してもらえたか"
  ],
  slide:"スライドは少なく、「なぜ」の1枚には写真か一文だけ、「3つの習慣」の1枚には大きな数字（1・2・3）と短い言葉だけを書きましょう。チームの前では、スライドより顔を見て話すことが大切です。"},
 {week:52, level:"B2", length:"10分＋質疑応答", title:"卒業：10分の提携最終プレゼン＋質疑応答",
  skill:"1年間で学んだ型と表現をすべて使い、インドの取引先に向けた10分の提携の最終プレゼンと、厳しい質問を含む質疑応答をやり切れる。",
  lesson:[
   "いよいよ最後の週です。1年前、30秒の自己紹介から始めた岩田さんが、今週は10分の提携の最終プレゼンと質疑応答に挑みます。これまでの型を全部つなげましょう。時間配分の目安は、はじめ1分（あいさつ・目的・今日の流れ）、自己紹介と相手の目標1分、提案3分、数字と費用対効果1分30秒、進め方と日程1分30秒、まとめと呼びかけ1分、の合計10分です。そのあと質疑応答に5〜10分をとります。",
   "スライドは10〜12枚が目安です（1分に1枚くらい）。表紙、今日の流れ、相手の目標、提案3枚、数字1枚、日程1枚、役割と条件1枚、まとめ1枚、質問のページ。そのうしろに、質問に答えるための予備のスライド（くわしい数字や流れ）を2〜3枚用意しておくと安心です。1枚の文字は少なく、話すことはメモではなく頭に入れておきます。",
   "緊張するのは、真剣な証拠です。本番の前は、①最初の3文だけは完全に暗記する ②ゆっくり息を吐いてから話し始める ③聞き手の中の、うなずいてくれる人を見つけて話す、の3つを試してください。言葉が出なくなったら、Let me put it another way.（別の言い方をします）と言って、やさしい言葉で言い直せば大丈夫です。どこまで話したかわからなくなったら、スライドを見て So, where was I? Yes, the timeline. と落ち着いて戻りましょう。",
   "質疑応答では、第48週の4つの手順（受け止める→確認する→答える→確かめる）を使います。わからない質問には期限つきで返事を約束し、反対意見にはまず気持ちを受け止めます。最後に大切なのは、完璧な英語ではなく、目の前の人に全力を尽くす姿勢です。今週の手本は、インドのホテル・ウェルネスのグループへの10分の最終プレゼンです。数字・期間・条件はすべて練習用の例です。1年間、本当によくがんばりました。"
  ],
  structure:[
   {en:"Opening, purpose and agenda (1 min)",ja:"はじめ：あいさつ・目的・今日の流れ（1分）"},
   {en:"Who we are and your goals (1 min)",ja:"私たちと、皆さんの目標（1分）"},
   {en:"The proposal: three pillars (3 min)",ja:"提案：3つの柱（3分）"},
   {en:"Numbers and value (1.5 min)",ja:"数字と費用対効果（1分30秒）"},
   {en:"Process, timeline and roles (1.5 min)",ja:"進め方・日程・役割（1分30秒）"},
   {en:"Summary, call to action, Q&A (1 min + Q&A)",ja:"まとめ・呼びかけ・質疑応答（1分＋質疑応答）"}
  ],
  phrases:[
   {en:"Namaste, and good morning, everyone. It's a real honour to stand here today.",ja:"ナマステ、皆さんおはようございます。今日ここに立てることを、心から光栄に思います。",note:"最初の3文は完全に暗記しておく。"},
   {en:"My presentation will take about ten minutes, and then I'd be happy to take your questions.",ja:"プレゼンは10分ほどで、そのあとご質問をお受けします。",note:"時間と質問のタイミングを最初に伝える。"},
   {en:"We understand that your goal is to become the first choice for guests from Japan.",ja:"皆さんの目標は、日本からのお客様に最初に選ばれることだと理解しています。",note:"相手の目標から提案に入る（第44週）。"},
   {en:"This would allow you to offer an experience your guests can't find anywhere else.",ja:"これで、お客様がほかのどこでも得られない体験をご提供できるようになります。",note:"相手の得で語る（第44週）。"},
   {en:"The investment will pay for itself in about six months.",ja:"この投資は、約6か月で元がとれます。",note:"費用対効果をひとことで（第43週）。"},
   {en:"Let me put it another way.",ja:"別の言い方をさせてください。",note:"言葉が出ないときの助け舟。やさしく言い直す。"},
   {en:"So, where was I? Yes, the timeline.",ja:"さて、どこまで話しましたっけ。そうそう、日程でした。",note:"話を見失ったら、落ち着いて戻る。"},
   {en:"If you could agree to a pilot today, we would start the preparation next week.",ja:"今日、試行にご同意いただけるなら、来週から準備を始めます。",note:"条件つきの呼びかけ（第42週）。"},
   {en:"To conclude, let me leave you with three key points.",ja:"まとめとして、3つの要点をお伝えして終わります。",note:"まとめに新しい話は出さない（第40週）。"},
   {en:"Thank you for your question. If I understand correctly, you're asking about the risk.",ja:"ご質問ありがとうございます。私の理解が正しければ、リスクについてのご質問ですね。",note:"質疑応答の4つの手順（第48週）。"}
  ],
  model:{title:"インドのホテル・ウェルネスのグループへの提携の最終プレゼン（10分）", time:"10分", note:"数字・金額・期間・条件・相手のグループの様子は練習用の例です。自分の内容に入れかえましょう。",
   lines:[
    {en:"Namaste, and good morning, everyone. It's a real honour to stand here today.",ja:"ナマステ、皆さんおはようございます。今日ここに立てることを、心から光栄に思います。"},
    {en:"Thank you for welcoming me to your head office, and for all the time you have given me over the past few months.",ja:"本社にお迎えいただき、またここ数か月、多くのお時間をいただいたことに感謝します。"},
    {en:"Today I'd like to present our final proposal for a partnership between your group and my team in Japan.",ja:"今日は、皆さんのグループと日本の私のチームとの提携について、最終のご提案をいたします。"},
    {en:"My presentation will take about ten minutes, and then I'd be happy to take your questions.",ja:"プレゼンは10分ほどで、そのあとご質問をお受けします。"},
    {en:"I'll cover five parts: your goals, our proposal, the numbers, how we will work together, and the next step.",ja:"5つの部分をお話しします。皆さんの目標、私たちの提案、数字、一緒にどう進めるか、そして次の一歩です。"},
    {en:"Let me start with a short introduction. I'm Akihiro Iwata, a licensed acupuncturist and judo therapist from Japan.",ja:"まず、手短に自己紹介をします。日本の鍼灸師・柔道整復師、岩田章弘です。"},
    {en:"I opened my clinic in Ozu, Ehime, in October 2018. Today we are a team of four staff.",ja:"2018年10月に愛媛県大洲市で院を開きました。今はスタッフ4名のチームです。"},
    {en:"Before that, I worked as an athletic trainer for high school, university, corporate and professional teams.",ja:"その前は、高校・大学・実業団・プロのチームでアスレティックトレーナーをしていました。"},
    {en:"I built a booking and customer management system for my clinic, and now I provide it to partner clinics with management support.",ja:"院のために予約と顧客管理のしくみを作り、今は経営のサポートとともに提携院に提供しています。"},
    {en:"I also support companies in India with hospitality consulting, and I'm the International Affairs Manager of my family's sake shop, founded in 1957.",ja:"また、インドの企業におもてなしのコンサルをしていて、1957年創業の家族の酒店では国際担当をしています。"},
    {en:"Now, your goals. We understand that your goal is to become the first choice for guests from Japan.",ja:"次に、皆さんの目標です。皆さんの目標は、日本からのお客様に最初に選ばれることだと理解しています。"},
    {en:"You also want your Indian guests, many of whom love Japan, to enjoy a wellness experience that feels truly special.",ja:"また、日本好きの方も多いインドのお客様に、本当に特別だと感じるウェルネスの体験を楽しんでいただきたいとお考えです。"},
    {en:"And you want more guests to come back. In your words, a guest who returns is worth more than a new one.",ja:"そして、もっと多くのお客様にもどってきてほしい。皆さんの言葉では、もどってくるお客様は新しいお客様より価値がある、ということでした。"},
    {en:"I agree completely. In my clinic, I check the rate of returning patients every day, because it shows whether people felt cared for.",ja:"まったく同感です。私の院では、毎日再来院率を確認しています。人が大切にされたと感じたかを示すからです。"},
    {en:"Moving on to our proposal. It stands on three pillars.",ja:"私たちの提案に移ります。3つの柱でできています。"},
    {en:"The first pillar is Japanese health and care know-how.",ja:"1つめの柱は、日本の健康とケアのノウハウです。"},
    {en:"We will train your therapists in simple Japanese care for posture, stiff shoulders and tired legs, especially after long flights.",ja:"セラピストの皆さんに、姿勢、こった肩、疲れた脚のための、日本のかんたんなケアをお伝えします。特に長いフライトのあとのケアです。"},
    {en:"We will design two menus: a twenty-minute session for business travellers, and a longer session for families on holiday.",ja:"2つのメニューを作ります。出張のお客様向けの20分のケアと、休暇中のご家族向けの長めのケアです。"},
    {en:"This would allow you to offer an experience your guests can't find anywhere else.",ja:"これで、お客様がほかのどこでも得られない体験をご提供できるようになります。"},
    {en:"The second pillar is omotenashi, combined with your own tradition of Atithi Devo Bhava.",ja:"2つめの柱は、おもてなしです。皆さん自身の Atithi Devo Bhava の伝統と合わせます。"},
    {en:"We will train your front desk and service teams to notice what a guest needs before the guest asks.",ja:"フロントとサービスのチームの皆さんに、お客様が頼む前に必要なことに気づく力をお伝えします。"},
    {en:"Three habits are at the centre: use the guest's name, greet within ten seconds, and note one small thing about each guest.",ja:"中心になるのは3つの習慣です。お客様の名前を呼ぶ、10秒以内にあいさつする、一人ひとりについて小さなことを1つ書きとめる。"},
    {en:"Let me give you an example. A guest from Tokyo arrives late at night, tired and quiet.",ja:"例を挙げます。東京からのお客様が、夜おそく、疲れて静かに到着します。"},
    {en:"Your staff greet her by name, offer a warm towel, and note that she prefers a quiet room and green tea.",ja:"スタッフが名前を呼んであいさつし、温かいおしぼりを出し、静かな部屋と緑茶が好きだと書きとめます。"},
    {en:"The next morning, a twenty-minute shoulder care session is offered before breakfast. That is omotenashi in action.",ja:"翌朝、朝食の前に20分の肩のケアをおすすめします。これが、おもてなしを形にするということです。"},
    {en:"The third pillar is our booking and customer system.",ja:"3つめの柱は、私たちの予約と顧客のしくみです。"},
    {en:"It shows each guest's history and preferences on one screen, and it sends a short message after each stay.",ja:"一人ひとりのお客様の記録と好みを1つの画面に出し、滞在のあとには短いメッセージを送ります。"},
    {en:"This would allow your staff to remember every guest, even when the hotel is very busy.",ja:"これで、ホテルがとても忙しいときでも、スタッフの皆さんがすべてのお客様を覚えていられます。"},
    {en:"And on top of these three pillars, we can offer Japanese evenings with sake from my family's shop.",ja:"そして3つの柱に加えて、家族の酒店の日本酒で、日本の夜をご提供できます。"},
    {en:"Each sake comes with a short story about its region, and there will always be vegetarian dishes and Japanese teas for guests who don't drink.",ja:"日本酒にはそれぞれ産地の短い物語を添え、お酒を飲まないお客様のために、ベジタリアンの料理と日本茶もいつもご用意します。"},
    {en:"That brings me to the numbers. Let's look at this as an investment, not a cost.",ja:"そこで、数字の話になります。これを費用ではなく、投資として見てみましょう。"},
    {en:"For one hotel, there is a one-time set-up fee of 300,000 rupees, which includes the system and four training days.",ja:"ホテル1つにつき、最初に1回だけ30万ルピーの導入費がかかります。しくみと4日間の研修が含まれます。"},
    {en:"After that, the monthly fee is 50,000 rupees for the system, reports and online support.",ja:"そのあとは毎月5万ルピーで、しくみ、報告、オンラインのサポートが含まれます。"},
    {en:"Now, the return. If each hotel gets about 25 more returning guests a month, and each guest spends about 4,000 rupees, that's 100,000 rupees.",ja:"次に回収です。ホテルごとに、もどってくるお客様が月に約25人ふえ、1人あたり約4,000ルピーを使うとすると、10万ルピーになります。"},
    {en:"Take away the monthly fee, and you keep about 50,000 rupees a month.",ja:"毎月の料金を引くと、毎月約5万ルピーが残ります。"},
    {en:"So the investment will pay for itself in about six months. After that, it's profit, and the habits stay with your team.",ja:"ですから、この投資は約6か月で元がとれます。そのあとは利益になり、習慣はチームに残ります。"},
    {en:"Of course, these figures are an estimate. We'll check them together with your real numbers before we start.",ja:"もちろん、これらは見込みの数字です。始める前に、皆さんの実際の数字で一緒に確かめます。"},
    {en:"There is also value that numbers can't show: more confident staff, warmer reviews, and a stronger reputation with guests from Japan.",ja:"数字では見えない価値もあります。自信を持ったスタッフ、温かい口コミ、そして日本からのお客様の間でのより強い評判です。"},
    {en:"Moving on to how we will work together. Let me walk you through the process step by step.",ja:"一緒にどう進めるかに移ります。流れを一つずつご説明します。"},
    {en:"First, your current service is observed, and a training plan is prepared. This takes about two weeks.",ja:"まず、今のサービスが観察され、研修の計画が作られます。約2週間かかります。"},
    {en:"Next, the system is set up and the guest messages are translated into English, Japanese and Hindi.",ja:"次に、しくみが準備され、お客様へのメッセージが英語・日本語・ヒンディー語に翻訳されます。"},
    {en:"Then the staff are trained at the hotel, and the new service is launched with a small group of guests.",ja:"それから、スタッフがホテルで研修を受け、新しいサービスが少人数のお客様で始まります。"},
    {en:"We suggest a three-month pilot at your Bengaluru hotel first. At the end, we'll review guest reviews and repeat bookings together.",ja:"まずベンガルールのホテルで3か月の試行をご提案します。最後に、お客様の評価とリピートの予約を一緒に見直します。"},
    {en:"In short, preparation in the first month, training and launch in the second month, and the review at the end of the third month.",ja:"つまり、1か月めに準備、2か月めに研修と開始、3か月めの終わりに見直しです。"},
    {en:"During the pilot, I will be at the hotel for the training, and I will support your team online every week.",ja:"試行の間、研修のときは私がホテルにいて、毎週オンラインでチームを支えます。"},
    {en:"If the results are good, we will bring the program to your other hotels, one by one.",ja:"結果がよければ、プログラムをほかのホテルにも、一つずつ広げます。"},
    {en:"As for roles, your team will focus on daily service, and we will support the training, the system and the reports.",ja:"役割については、皆さんのチームは日々のサービスに集中し、私たちは研修、しくみ、報告を支えます。"},
    {en:"All guest data belongs to your hotel, and either side may end the agreement with 60 days' notice.",ja:"お客様のデータはすべて皆さんのホテルのもので、どちらの側も60日前に知らせれば契約を終了できます。"},
    {en:"So, why us? Let me put it simply. We bring practical experience from a real clinic, not just theory.",ja:"では、なぜ私たちなのか。かんたんに申し上げます。私たちは理論だけでなく、実際の院での現場の経験をお持ちします。"},
    {en:"We are not a big company. But I will be personally responsible for this project, from the first day to the review.",ja:"私たちは大きな会社ではありません。でも、このプロジェクトには、初日から見直しまで、私自身が責任を持ちます。"},
    {en:"In my work, I've always followed one simple rule: give your full effort to the person in front of you.",ja:"私は仕事で、いつも1つのシンプルな決まりを守ってきました。目の前の人に全力を尽くすことです。"},
    {en:"Today, the people in front of me are you and your guests.",ja:"今日、私の目の前にいるのは、皆さんと、皆さんのお客様です。"},
    {en:"To conclude, let me leave you with three key points.",ja:"まとめとして、3つの要点をお伝えして終わります。"},
    {en:"First, our three pillars, Japanese care, omotenashi and a simple customer system, help your guests feel truly cared for.",ja:"1つめ、日本のケア、おもてなし、かんたんな顧客のしくみという3つの柱が、お客様に本当に大切にされたと感じていただく助けになります。"},
    {en:"Second, the investment can pay for itself in about six months, and we will check the numbers together.",ja:"2つめ、投資は約6か月で元がとれる見込みで、数字は一緒に確かめます。"},
    {en:"Third, we start small and safe, with a three-month pilot at one hotel.",ja:"3つめ、1つのホテルでの3か月の試行から、小さく安心して始めます。"},
    {en:"If you could agree to a pilot today, we would start the preparation next week, and your guests would feel the difference by spring.",ja:"今日、試行にご同意いただけるなら、来週から準備を始め、春にはお客様がちがいを感じてくださるはずです。"},
    {en:"A year ago, I started learning to present in English with a thirty-second self-introduction. Today I'm standing here, ready to build something new with you.",ja:"1年前、私は30秒の自己紹介から英語のプレゼンを学び始めました。今日、皆さんと新しいものをつくる準備をして、ここに立っています。"},
    {en:"Thank you very much for listening. Dhanyavaad. Now I'd be happy to take your questions.",ja:"ご清聴、本当にありがとうございました。ダンニャワード。それでは、ご質問をお受けします。"}
   ]},
  task:"1年間のまとめとして、インドのホテル・ウェルネスのグループに向けて、提携の最終プレゼンを10分で行い、そのあとAIからの5つの質問（厳しい質問・反対意見・わからない質問を含む）に答える。スライドは10〜12枚、予備のスライドも用意する。",
  taskEn:"As your graduation test, give a 10-minute final partnership presentation to a hotel and wellness group in India. Then answer five questions from me, including tough questions, an objection and one you can't answer right away.",
  qa:[
   {q:"Your numbers look optimistic. What if returning guests increase by only ten a month?",a:"Thank you for that question. You're right to check. With ten more guests, you would earn about 40,000 rupees, so the payback would take longer. That's why we start with a pilot and review the real numbers after three months before you invest more.",ja:"数字が楽観的に見えます。もどってくるお客様が月に10人しかふえなかったら？／ご質問ありがとうございます。確かめていただくのは正しいことです。10人なら約4万ルピーなので、回収にはもっと時間がかかります。だからこそ試行から始め、さらに投資していただく前に、3か月後に実際の数字を見直すのです。"},
   {q:"Honestly, we can hire a local trainer for much less. Why should we pay for you?",a:"I understand your concern. A local trainer knows your city very well. What we add is clinical care experience, a proven system and omotenashi from Japan. In fact, I'd be happy to work with a local trainer, so that your team keeps the skills after I leave.",ja:"率直に言って、地元のトレーナーならずっと安く雇えます。なぜあなたにお金を払うべきなのですか？／ご心配はわかります。地元のトレーナーは街のことをよくご存じです。私たちが加えるのは、臨床のケアの経験、実際に使われているしくみ、そして日本のおもてなしです。実は、地元のトレーナーの方とぜひ一緒に働きたいと思っています。そうすれば、私が去ったあともチームに技術が残ります。"},
   {q:"What happens if you get sick or can't travel to India during the pilot?",a:"That's an important question. The training materials and the system are ready in advance, so the work doesn't stop. I can support the team online, and we would agree on new dates for any visits. I'll add a clear plan for this to the contract.",ja:"試行の間に、あなたが病気になったりインドに来られなくなったりしたら？／大切なご質問です。研修の資料としくみは前もって準備しているので、仕事は止まりません。オンラインでチームを支え、訪問の日程は新しく決め直します。このための計画を、はっきり契約に加えます。"},
   {q:"Are there any rules in India about importing sake for hotel events?",a:"That's a good question. I don't have the exact answer right now, because the rules depend on the state and the licence. I'll check with an importer and get back to you by next Friday.",ja:"ホテルのイベントのために日本酒を輸入することについて、インドのきまりはありますか？／よいご質問です。州や許可によってきまりがちがうので、今は正確な答えを持っていません。輸入業者に確認して、来週の金曜までにご連絡します。"},
   {q:"If we sign today, can you guarantee the results?",a:"Let me be honest. I can't guarantee numbers, because every hotel is different. What I can guarantee is my full effort and clear reports every month. And you are free to stop after the pilot if the results are not good enough.",ja:"今日サインしたら、成果を保証してくれますか？／正直に申し上げます。ホテルごとに事情がちがうので、数字は保証できません。保証できるのは、私の全力と、毎月のわかりやすい報告です。そして成果が足りなければ、試行のあとでやめていただけます。"}
  ],
  check:[
   "10分の時間配分（はじめ1分・提案3分・数字1分30秒・進め方1分30秒・まとめ1分など）を守れたか",
   "これまでの型（道しるべ・データ・条件・相手の得・受け身・まとめ）をそれぞれ1回以上使えたか",
   "最初の3文を暗記して、落ち着いて話し始められたか",
   "厳しい質問・反対意見・わからない質問に、4つの手順で、うそをつかずに答えられたか",
   "経歴は本当のことだけで、数字は「見込み」として正直に話せたか"
  ],
  slide:"スライドは10〜12枚（1分に1枚が目安）。最後の「まとめ」には3つの要点と次の一歩だけを書き、そのうしろに質問用の予備のスライド（くわしい数字・流れ・条件）を2〜3枚用意しましょう。"}
]);
